-- Exact post-auth source qualification bodies from original reader/helpers.
-- No new resolver and no identity substitution. Only called after original Root locks.
CREATE OR REPLACE FUNCTION place_actions_private.ask_knowledge_scope_v1(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare instant timestamptz; result jsonb;
begin
 if not knowledge_review_private.closed_object(p_input,array['city','scene','locale'])
  or coalesce(p_input->>'city','') not in ('shanghai','beijing','guangzhou','chongqing')
  or coalesce(p_input->>'scene','') not in ('arrival','airport_transport','payment','connectivity','public_transport','taxi','rail','attraction','accommodation','emergency')
  or coalesce(p_input->>'locale','') not in ('zh','en') then raise exception 'INVALID_INPUT'; end if;
 perform 1 from knowledge_review_private.publication_settings where singleton and enabled for share;
 if not found then raise exception 'KNOWLEDGE_DISABLED'; end if;
 -- Serialize each read with a committed revocation; a receipt is never permanent eligibility.
 perform p.candidate_id from knowledge_review_private.publications p join knowledge_review_private.statements s on s.candidate_id=p.candidate_id
 where p.state='published' and s.payload->'scope'->'cities' ? (p_input->>'city') and s.payload->'scope'->>'scene'=p_input->>'scene' order by p.candidate_id for share of p;
 instant:=clock_timestamp();
 select coalesce(jsonb_agg(x.row order by x.id),'[]'::jsonb) into result from (
  select p.fact_id id,jsonb_build_object('factId',p.fact_id,'version',1,'assertionId',s.statement_id,'assertionRevision',s.revision,
   'assertion',s.payload->'assertion','scope',s.payload->'scope','text',s.payload->'expressions'->(p_input->>'locale')->>'text',
   'conditions',s.payload->'expressions'->(p_input->>'locale')->'conditions','exclusions',s.payload->'expressions'->(p_input->>'locale')->'exclusions',
   'reviewedAt',c.reviewed_at,'publishedAt',p.published_at,'expiresAt',p.expires_at,
   'sources',(select jsonb_agg(jsonb_build_object('sourceRevisionId',r.id,'sourceKey',r.source_key,'revisionLabel',r.revision_label,'publisher',r.declaration->>'publisher','uri',r.declaration->>'uri','locator',r.declaration->>'locator') order by r.source_key,r.revision_label) from knowledge_review_private.statement_sources ss join knowledge_review_private.source_revisions r on r.id=ss.source_revision_id where ss.candidate_id=c.id)) row
  from knowledge_review_private.publications p join knowledge_review_private.statements s on s.candidate_id=p.candidate_id join knowledge_review_private.candidates c on c.id=p.candidate_id
  where p.state='published' and p.expires_at>instant and c.status='reviewed' and s.payload->'scope'->'cities' ? (p_input->>'city') and s.payload->'scope'->>'scene'=p_input->>'scene'
  order by p.fact_id limit 50
 ) x;
 return jsonb_build_object('schemaVersion','knowledge-read/1','evaluatedAt',instant,'scope',p_input,
  'purpose','trip_planning','recipient','first_party','territory','CN-mainland','status',case when jsonb_array_length(result)>0 then 'available' else 'no_eligible_content' end,'statements',result);
end $function$
;
revoke all on function place_actions_private.ask_knowledge_scope_v1(jsonb) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION place_actions_private.ask_claim_basis_v1(p_statement uuid, p_revision integer, p_hash text, p_city text, p_scene text, p_locale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare st knowledge_review_private.statements%rowtype;p knowledge_review_private.publications%rowtype;c knowledge_review_private.candidates%rowtype;readback jsonb;found_fact jsonb;sources jsonb;
begin
 select * into st from knowledge_review_private.statements where statement_id=p_statement for share nowait;if not found or st.revision is distinct from p_revision or trip_support_private.hash(st.payload) is distinct from p_hash then return null;end if;
 select * into p from knowledge_review_private.publications where candidate_id=st.candidate_id for share nowait;if not found or p.state<>'published' or p.expires_at<=clock_timestamp() then return null;end if;
 select * into c from knowledge_review_private.candidates where id=st.candidate_id for share nowait;if not found or c.status<>'reviewed' then return null;end if;
 readback:=place_actions_private.ask_knowledge_scope_v1(jsonb_build_object('city',p_city,'scene',p_scene,'locale',p_locale));
 select x into found_fact from jsonb_array_elements(readback->'statements') x where x->>'factId'=p.fact_id::text and x->>'assertionId'=st.statement_id::text and x->>'assertionRevision'=st.revision::text;
 if found_fact is null then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('sourceRevisionId',r.id,'revisionLabel',r.revision_label,'snippetHash',r.snippet_hash,'submittedBy',r.submitted_by) order by r.id),'[]'::jsonb) into sources from knowledge_review_private.statement_sources ss join knowledge_review_private.source_revisions r on r.id=ss.source_revision_id where ss.candidate_id=st.candidate_id and r.withdrawn_at is null;
 if jsonb_array_length(sources) not between 1 and 8 or jsonb_array_length(sources)<>(select count(*) from knowledge_review_private.statement_sources where candidate_id=st.candidate_id) then return null;end if;
 return jsonb_build_object('statementId',st.statement_id,'claimRevision',st.revision,'payloadHash',p_hash,'payload',st.payload,'sourceRefs',sources,'sourceDigest',trip_support_private.hash(sources),'receipt',jsonb_build_object('kind','fact','factId',p.fact_id,'version',p.version,'reviewedAt',c.reviewed_at,'expiresAt',p.expires_at));
exception when lock_not_available then return null;end $function$
;
revoke all on function place_actions_private.ask_claim_basis_v1(uuid,integer,text,text,text,text) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION place_actions_private.ask_mapping_basis_v1(p_mapping uuid, p_require_approved boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m trip_support_private.entity_mappings%rowtype;p public.canonical_pois%rowtype;basis jsonb;member_revision bigint;
begin
 select * into m from trip_support_private.entity_mappings where id=p_mapping;if not found or p_require_approved and m.status<>'approved' then return null;end if;
 select * into p from public.canonical_pois where id=m.canonical_poi_id for share nowait;if not found or trip_support_private.hash(to_jsonb(p))<>m.canonical_hash then return null;end if;
 if p_require_approved then select revision into member_revision from knowledge_review_private.members where actor_id=m.reviewer_id and active for share nowait;if member_revision is distinct from m.reviewer_member_revision then return null;end if;end if;
 basis:=place_actions_private.ask_claim_basis_v1(m.statement_id,m.claim_revision,m.payload_hash,m.basis_metadata->>'city',m.basis_metadata->>'scene',m.basis_metadata->>'locale');if basis is null or basis->>'sourceDigest'<>m.source_digest or basis->'sourceRefs' is distinct from m.source_refs then return null;end if;
 return basis||jsonb_build_object('mappingId',m.id,'mappingVersion',m.version,'mappingDigest',m.request_digest,'canonicalPoiId',m.canonical_poi_id);
exception when lock_not_available then return null;end $function$
;
revoke all on function place_actions_private.ask_mapping_basis_v1(uuid,boolean) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION place_actions_private.ask_sources_v1(poi uuid, loc text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare m trip_support_private.entity_mappings%rowtype;b jsonb;c jsonb;scope text;rows jsonb:='[]';n integer:=0;expiry timestamptz:=clock_timestamp()+interval '30 seconds';
begin
 -- The publication reader being disabled is unavailable, not a complete empty result.
 perform 1 from knowledge_review_private.publication_settings where singleton and enabled for share;
 if not found then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
 for m in select * from trip_support_private.entity_mappings where canonical_poi_id=poi and status='approved' and basis_metadata->>'locale'=loc order by id limit 501 for share loop
  n:=n+1;if n>500 then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
  if m.version>2147483647 then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
  b:=place_actions_private.ask_mapping_basis_v1(m.id);if b is null then continue;end if;
  scope:=case b->'payload'->'assertion'->>'predicate' when 'located_at' then 'address_reference' when 'opens_during' then 'opening_window_reference' end;
  c:=trip_support_private.typed_claim(b,scope);if c is null then continue;end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('mappingId',m.id,'mappingVersion',m.version,'mappingDigest',m.request_digest,'statementId',m.statement_id,'claimRevision',m.claim_revision,'payloadHash',m.payload_hash,'sourceDigest',m.source_digest,'scope',scope,'claim',c,'city',m.basis_metadata->>'city','scene',m.basis_metadata->>'scene','locale',loc));
  expiry:=least(expiry,(b->'receipt'->>'expiresAt')::timestamptz);
  if jsonb_array_length(rows)>24 then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end if;
 end loop;
 return jsonb_build_object('status','complete','entries',rows,'expiresAt',expiry);
exception when lock_not_available then return jsonb_build_object('status','unavailable','entries','[]'::jsonb,'expiresAt',expiry);end $function$
;
revoke all on function place_actions_private.ask_sources_v1(uuid,text) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_uuid_v1(v jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(jsonb_typeof(v)='string' and v#>>'{}' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',false)
$$;
revoke all on function place_actions_private.ask_uuid_v1(jsonb) from public,anon,authenticated,service_role;
create or replace function place_actions_private.ask_expectation_shape_v1(e jsonb) returns boolean language plpgsql immutable set search_path='' as $$
begin
 if not place_actions_private.exact_v1(e,array['tripId','headVersion','canonicalPoiId','provider','providerPoiId','mappingDigest','contextDigest','referenceId','locale'])
 or not place_actions_private.ask_uuid_v1(e->'tripId') or not place_actions_private.ask_uuid_v1(e->'canonicalPoiId') or not place_actions_private.revision_v1(e->'headVersion')
 or not place_actions_private.selection_v1(jsonb_set(e-array['tripId','headVersion','mappingDigest','contextDigest','referenceId','locale'],'{canonicalPoiId}',to_jsonb(lower(e->>'canonicalPoiId'))))
 or coalesce(e->>'locale','') not in('zh','en') or jsonb_typeof(e->'mappingDigest') is distinct from 'string' or e->>'mappingDigest' !~ '^[a-f0-9]{64}$'
 or jsonb_typeof(e->'contextDigest') is distinct from 'string' or e->>'contextDigest' !~ '^[a-f0-9]{64}$'
 or (e->'referenceId'<>'null'::jsonb and not place_actions_private.ask_uuid_v1(e->'referenceId')) then return false;end if;
 return true;
end $$;
revoke all on function place_actions_private.ask_expectation_shape_v1(jsonb) from public,anon,authenticated,service_role;

-- AGENT005_REAL_SQL_IMPLEMENTATION: private current qualification, no new resolver or ordinary grant.
CREATE OR REPLACE FUNCTION place_actions_private.ask_context_v1(u uuid, actor_session uuid, p_trip uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare t public.trips%rowtype;m jsonb;s place_actions_private.saved_places%rowtype;r uuid;saved jsonb;basis jsonb;src jsonb;stamp timestamptz;snapshot jsonb;
begin
 if u is null or actor_session is null or not exists(select 1 from auth.sessions where id=actor_session and user_id=u) then raise exception 'UNAUTHENTICATED';end if;
 if p_input->>'action'='saved' then return place_actions_private.saved_v1(p_trip,p_input,u);end if;
 if not place_actions_private.valid_v1(p_input,true) then raise exception 'INVALID_INPUT';end if;
 select * into t from public.trips where id=p_trip and owner_id=u for share;if not found then raise exception 'FORBIDDEN';end if;
 if exists(select 1 from public.trip_archives where trip_id=t.id) or exists(select 1 from privacy_private.trip_deletions where trip_id=t.id) then return jsonb_build_object('kind','unavailable','reason','ARCHIVED');end if;
 if t.head_version<>(p_input->>'expectedTripVersion')::numeric then return jsonb_build_object('kind','unavailable','reason','STALE_TRIP_VERSION');end if;
 if (select count(*) from public.trip_place_references where trip_id=t.id)>100 or (select count(*) from public.trip_days where trip_id=t.id)>100 or (select count(*) from public.trip_items where trip_id=t.id)>500 then return jsonb_build_object('kind','unavailable','reason','CAPACITY');end if;
 m:=place_actions_private.mapping_v1(p_input->'selection');if m is null then return jsonb_build_object('kind','unavailable','reason',case when exists(select 1 from public.canonical_pois where id=(p_input->'selection'->>'canonicalPoiId')::uuid) then 'MAPPING_CHANGED' else 'PLACE_NOT_FOUND' end);end if;
 select * into s from place_actions_private.saved_places where owner_id=u and trip_id=t.id and canonical_poi_id=(p_input->'selection'->>'canonicalPoiId')::uuid for share;
 if found then
  perform 1 from public.trip_place_references where id=s.reference_id and trip_id=t.id and owner_id=u and canonical_poi_id=s.canonical_poi_id and reference_kind='canonical';if not found then raise exception 'PLACE_ACTION_UNAVAILABLE';end if;
  saved:=jsonb_build_object('referenceId',s.reference_id,'revision',s.revision,'status',s.status,'mappingDigest',s.mapping_digest);r:=s.reference_id;
 else select id into r from public.trip_place_references where trip_id=t.id and owner_id=u and reference_kind='canonical' and canonical_poi_id=(p_input->'selection'->>'canonicalPoiId')::uuid order by created_at,id limit 1;end if;
 snapshot:=place_actions_private.snapshot_v1(t.id,t.title,t.head_version);
 if place_actions_private.utf16_length_v1(m->>(p_input->>'locale'))>160 or place_actions_private.utf16_length_v1(t.title)>160 or exists(select 1 from public.trip_items where trip_id=t.id and place_actions_private.utf16_length_v1(title)>160) then return jsonb_build_object('kind','unavailable','reason','CAPACITY');end if;
 src:=place_actions_private.ask_sources_v1((p_input->'selection'->>'canonicalPoiId')::uuid,p_input->>'locale');
 basis:=jsonb_build_object('kind','place_action_context','tripId',t.id,'tripVersion',t.head_version,'selection',p_input->'selection','mappingDigest',m->>'digest','snapshot',snapshot,'displayTitle',m->>(p_input->>'locale'),'referenceId',r,'saved',saved,'sourceCandidates',src->'entries','sourceCandidatesStatus',src->>'status');
 stamp:=clock_timestamp();
 return basis||jsonb_build_object('contextDigest',place_actions_private.hash_v1(jsonb_build_object('owner',u,'session',actor_session::text,'basis',basis)),'evaluatedAt',recovery_private.ms_v1(stamp),'expiresAt',recovery_private.ms_v1(least(stamp+interval '30 seconds',(src->>'expiresAt')::timestamptz)));
exception when lock_not_available then raise exception 'PLACE_ACTION_UNAVAILABLE';end $function$
;
revoke all on function place_actions_private.ask_context_v1(uuid,uuid,uuid,jsonb) from public,anon,authenticated,service_role;

-- The helper is private and called only after original owner/session/worker locks.
-- This reads the original mapping/source chain, never names or model output.
create or replace function place_actions_private.ask_basis_v1(u uuid,s uuid,e jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v jsonb;rows jsonb;subject text;city text;scene text;begin
 if not place_actions_private.ask_expectation_shape_v1(e) then raise exception 'INVALID_INPUT';end if;
 v:=place_actions_private.ask_context_v1(u,s,(e->>'tripId')::uuid,jsonb_build_object('action','context','expectedTripVersion',e->'headVersion','selection',jsonb_set(e-array['tripId','headVersion','mappingDigest','contextDigest','referenceId','locale'],'{canonicalPoiId}',to_jsonb(lower(e->>'canonicalPoiId'))),'locale',e->'locale'));
 if v->>'kind' is distinct from 'place_action_context' or v->'mappingDigest' is distinct from e->'mappingDigest'
 or v->'contextDigest' is distinct from e->'contextDigest' or (v->>'referenceId')::uuid is distinct from (e->>'referenceId')::uuid
 then raise exception 'MAPPING_CHANGED';end if;
 if v->>'sourceCandidatesStatus' is distinct from 'complete' or jsonb_array_length(v->'sourceCandidates')=0 then raise exception 'PLACE_ASK_SOURCE_UNAVAILABLE';end if;
 rows:=v->'sourceCandidates';
 if exists(select 1 from jsonb_array_elements(rows)x where x->>'locale' is distinct from e->>'locale'
 or x->>'city' not in('shanghai','beijing','guangzhou','chongqing') or nullif(x->'claim'->>'subjectId','') is null or nullif(x->>'scene','') is null)
 or (select count(distinct jsonb_build_array(x->'claim'->'subjectId',x->'city',x->'scene',x->'locale')) from jsonb_array_elements(rows)x)<>1 then raise exception 'PLACE_ASK_SELECTION_AMBIGUOUS';end if;
 select x->'claim'->>'subjectId',x->>'city',x->>'scene' into subject,city,scene from jsonb_array_elements(rows)x limit 1;
 return jsonb_build_object('subjectId',subject,'city',city,'scene',scene,'sourceDigest',place_actions_private.hash_v1(rows));
end $$;
revoke all on function place_actions_private.ask_basis_v1(uuid,uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_proof_shape_v1(v jsonb) returns boolean language sql immutable set search_path='' as $$
 select coalesce(place_actions_private.exact_v1(v,array['schemaVersion','operationId','scopeKind','scopeId','operation','requestDigest','expectation','basis','originalReceipt'])
 and place_actions_private.ask_expectation_shape_v1(v->'expectation')
 and place_actions_private.exact_v1(v->'operation',array['operationId','scopeKind','scopeId','messageId','turnId'])
 and v->'operation'->'operationId'=v->'operationId' and v->'operation'->'scopeId'=v->'scopeId' and v->'operation'->'scopeKind'=v->'scopeKind'
 and v->'operation'->'messageId'='null'::jsonb and v->'operation'->'turnId'=v->'originalReceipt'->'turnId'
 and v->'basis'->'city' is not null and v->'expectation'->'locale' is not null
 and v->>'schemaVersion'='canonical-place-proof/1' and v->>'scopeKind'='thread'
 and place_actions_private.ask_uuid_v1(v->'operationId') and place_actions_private.ask_uuid_v1(v->'scopeId')
 and jsonb_typeof(v->'requestDigest')='string' and v->>'requestDigest' ~ '^[a-f0-9]{64}$'
 and place_actions_private.exact_v1(v->'basis',array['subjectId','city','scene','sourceDigest'])
 and v->'basis'->>'city' in('shanghai','beijing','guangzhou','chongqing')
 and jsonb_typeof(v->'basis'->'subjectId')='string' and length(v->'basis'->>'subjectId') between 1 and 160
 and jsonb_typeof(v->'basis'->'scene')='string' and length(v->'basis'->>'scene') between 1 and 80
 and jsonb_typeof(v->'basis'->'sourceDigest')='string' and v->'basis'->>'sourceDigest' ~ '^[a-f0-9]{64}$'
 and place_actions_private.exact_v1(v->'originalReceipt',array['version','kind','turnId','reused','serviceTaskId','scopeVersion','relationship','parentTurnId'])
 and v->'originalReceipt'->>'kind'='accepted' and v->'originalReceipt'->'version'='2'::jsonb
 and v->'originalReceipt'->'reused'='false'::jsonb
 and place_actions_private.ask_uuid_v1(v->'originalReceipt'->'turnId') and place_actions_private.ask_uuid_v1(v->'originalReceipt'->'serviceTaskId')
 and v->'originalReceipt'->'scopeVersion'='1'::jsonb and v->'originalReceipt'->>'relationship' in('new_goal','clarification','repair')
 and (v->'originalReceipt'->'parentTurnId'='null'::jsonb or place_actions_private.ask_uuid_v1(v->'originalReceipt'->'parentTurnId'))
 and ((v->'originalReceipt'->>'relationship'='new_goal')=(v->'originalReceipt'->'parentTurnId'='null'::jsonb)),false)
$$;
revoke all on function place_actions_private.ask_proof_shape_v1(jsonb) from public,anon,authenticated,service_role;
alter table turn_private.grounded_turns add column selected_place_request jsonb;
alter table turn_private.grounded_turns add constraint grounded_selected_place_request_shape check(selected_place_request is null or place_actions_private.ask_proof_shape_v1(selected_place_request));

create or replace function place_actions_private.ask_root_current_v1(tid uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare g turn_private.grounded_turns%rowtype;c turn_private.text_content%rowtype;w turn_private.work%rowtype;p jsonb;b jsonb;begin
 select * into g from turn_private.grounded_turns where turn_id=tid;
 if not found or g.selected_place_request is null then return null;end if;
 p:=g.selected_place_request;
 if not place_actions_private.ask_proof_shape_v1(p) then return null;end if;
 select * into w from turn_private.work where turn_id=tid and owner_id=g.owner_id;
 if not found then return null;end if;
 if exists(select 1 from identity_private.mobile_attempts where session_id=w.session_id) and not exists(select 1 from identity_private.mobile_attempts x join identity_private.mobile_accounts a on a.owner_id=x.owner_id and a.session_id=x.session_id and a.epoch=x.epoch where x.owner_id=g.owner_id and x.session_id=w.session_id) then return null;end if;

 select * into c from turn_private.text_content where turn_id=tid and owner_id=g.owner_id and hidden_at is null;
 if not found or not turn_private.text_policy_current(c.policy_id)
 or not exists(select 1 from turn_private.text_consents where owner_id=g.owner_id and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null)
 or exists(select 1 from public.turns where id=tid and status='cancelled') or exists(select 1 from turn_private.work where turn_id=tid and state='cancelled')
 or not exists(select 1 from turn_private.service_task_turns st join turn_private.service_tasks t on t.id=st.task_id and t.owner_id=st.owner_id
 join turn_private.text_content root on root.turn_id=t.goal_turn_id and root.owner_id=t.owner_id and root.hidden_at is null
 where st.turn_id=tid and st.owner_id=g.owner_id and st.task_id=g.task_id and st.idempotency_key=(p->>'operationId')::uuid
 and st.relationship=p->'originalReceipt'->>'relationship' and st.parent_turn_id is not distinct from (p->'originalReceipt'->>'parentTurnId')::uuid
 and t.thread_id=(p->>'scopeId')::uuid and c.thread_id=t.thread_id and t.policy_id=c.policy_id and t.consent_id=c.consent_id
 and st.request_digest=encode(sha256(convert_to(jsonb_build_array(c.thread_id,c.turn_id,st.idempotency_key,c.policy_id,c.locale,c.input_text,t.id,t.scope_version,st.relationship,st.parent_turn_id)::text,'UTF8')),'hex'))
 or p->'originalReceipt'->>'turnId' is distinct from tid::text or p->'originalReceipt'->>'serviceTaskId' is distinct from g.task_id::text
 or g.city is distinct from p->'basis'->>'city' or g.locale is distinct from p->'expectation'->>'locale' then return null;end if;
 -- Stored proof is a witness, never a grant. Requalify the original source chain.
 begin b:=place_actions_private.ask_basis_v1(g.owner_id,w.session_id,p->'expectation');
 exception when raise_exception then return null;end;
 if b is distinct from p->'basis' then return null;end if;
 return p;
end $$;
revoke all on function place_actions_private.ask_root_current_v1(uuid) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_bound_v1(tid uuid,token uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare g turn_private.grounded_turns%rowtype;c turn_private.text_content%rowtype;w turn_private.work%rowtype;p jsonb;b jsonb;begin
 select * into g from turn_private.grounded_turns where turn_id=tid;
 if not found or g.selected_place_request is null then return null;end if;
 p:=g.selected_place_request;
 if not place_actions_private.ask_proof_shape_v1(p) then return null;end if;
 select * into w from turn_private.work where turn_id=tid and owner_id=g.owner_id;
 if not found then return null;end if;
 if exists(select 1 from identity_private.mobile_attempts where session_id=w.session_id) and not exists(select 1 from identity_private.mobile_attempts x join identity_private.mobile_accounts a on a.owner_id=x.owner_id and a.session_id=x.session_id and a.epoch=x.epoch where x.owner_id=g.owner_id and x.session_id=w.session_id) then return null;end if;
 if token is null then
  if auth.uid() is distinct from g.owner_id or auth.jwt()->>'session_id' is distinct from w.session_id::text then return null;end if;
  perform turn_private.text_owner();
  if not turn_private.lock_turn(tid,g.owner_id,w.session_id) then return null;end if;
 else
  if not turn_private.lock_text_work(tid,token) then return null;end if;
 end if;
 select * into c from turn_private.text_content where turn_id=tid and owner_id=g.owner_id and hidden_at is null;
 if not found or not turn_private.text_policy_current(c.policy_id)
 or not exists(select 1 from turn_private.text_consents where owner_id=g.owner_id and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null)
 or exists(select 1 from public.turns where id=tid and status='cancelled') or exists(select 1 from turn_private.work where turn_id=tid and state='cancelled')
 or not exists(select 1 from turn_private.service_task_turns st join turn_private.service_tasks t on t.id=st.task_id and t.owner_id=st.owner_id
 join turn_private.text_content root on root.turn_id=t.goal_turn_id and root.owner_id=t.owner_id and root.hidden_at is null
 where st.turn_id=tid and st.owner_id=g.owner_id and st.task_id=g.task_id and st.idempotency_key=(p->>'operationId')::uuid
 and st.relationship=p->'originalReceipt'->>'relationship' and st.parent_turn_id is not distinct from (p->'originalReceipt'->>'parentTurnId')::uuid
 and t.thread_id=(p->>'scopeId')::uuid and c.thread_id=t.thread_id and t.policy_id=c.policy_id and t.consent_id=c.consent_id
 and st.request_digest=encode(sha256(convert_to(jsonb_build_array(c.thread_id,c.turn_id,st.idempotency_key,c.policy_id,c.locale,c.input_text,t.id,t.scope_version,st.relationship,st.parent_turn_id)::text,'UTF8')),'hex'))
 or p->'originalReceipt'->>'turnId' is distinct from tid::text or p->'originalReceipt'->>'serviceTaskId' is distinct from g.task_id::text
 or g.city is distinct from p->'basis'->>'city' or g.locale is distinct from p->'expectation'->>'locale' then return null;end if;
 -- Stored proof is a witness, never a grant. Requalify the original source chain.
 begin b:=place_actions_private.ask_basis_v1(g.owner_id,w.session_id,p->'expectation');
 exception when raise_exception then return null;end;
 if b is distinct from p->'basis' then return null;end if;
 return p;
end $$;
revoke all on function place_actions_private.ask_bound_v1(uuid,uuid) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_receipt_v1(tid uuid,p jsonb) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','accepted','operation',p->'operation','originalReceipt',p->'originalReceipt',
 'binding',jsonb_build_object('turnId',tid,'serviceTaskId',p->'originalReceipt'->'serviceTaskId','goalId',null,'goalVersion',null,'requestDigest',p->'requestDigest','expectation',p->'expectation'),
 'readyForProvider',false,'currentEligibilityRequiresRead',true)
$$;
revoke all on function place_actions_private.ask_receipt_v1(uuid,jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_submit_v1(request_bytes text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=place_actions_private.actor_v1();s uuid:=(auth.jwt()->>'session_id')::uuid;v jsonb:=request_bytes::jsonb;r jsonb:=v->'submission';e jsonb:=v->'expectation';b jsonb;old turn_private.grounded_turns%rowtype;receipt jsonb;p jsonb;tid uuid;begin
 if not place_actions_private.exact_v1(v,array['schemaVersion','submission','expectation']) or v->>'schemaVersion' is distinct from 'canonical-place-ask/1' or octet_length(request_bytes)>24000 then raise exception 'INVALID_INPUT';end if;
 -- The original assistant envelope does not admit a Task Turn. Do not invent one.
 if r ? 'conversationId' then return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','unavailable','reason','original_submission_unsupported','readyForProvider',false);end if;
 if not place_actions_private.exact_v1(r,array['threadId','turnId','idempotencyKey','policyId','locale','text','serviceTask'])
 or not place_actions_private.exact_v1(r->'serviceTask',array['id','scopeVersion','relationship','parentTurnId'])
 or not place_actions_private.ask_uuid_v1(r->'threadId') or not place_actions_private.ask_uuid_v1(r->'turnId') or not place_actions_private.ask_uuid_v1(r->'idempotencyKey')
 or not place_actions_private.ask_uuid_v1(r->'policyId') or not place_actions_private.ask_uuid_v1(r->'serviceTask'->'id')
 or r->'serviceTask'->'scopeVersion' is distinct from '1'::jsonb
 or coalesce(r->'serviceTask'->>'relationship','') not in('new_goal','clarification','repair')
 or ((r->'serviceTask'->>'relationship'='new_goal') is distinct from (r->'serviceTask'->'parentTurnId'='null'::jsonb))
 or (r->'serviceTask'->'parentTurnId'<>'null'::jsonb and not place_actions_private.ask_uuid_v1(r->'serviceTask'->'parentTurnId'))
 or jsonb_typeof(r->'text') is distinct from 'string' or not turn_private.valid_text(r->>'text',4000)
 or coalesce(r->>'locale','') not in('zh','en') or r->'locale' is distinct from e->'locale' then raise exception 'INVALID_INPUT';end if;
 tid:=(r->>'turnId')::uuid;
 -- Account/auth first, mobile UPDATE then 34, then operation/root/Trip/context.
 perform 1 from identity_private.mobile_accounts where owner_id=u for update;
 perform pg_advisory_xact_lock(hashtextextended(u::text,34));
 perform pg_advisory_xact_lock(hashtextextended('selected-place:'||u::text||':'||(r->>'idempotencyKey'),0));
 select g.* into old from turn_private.grounded_turns g where owner_id=u and (selected_place_request->>'operationId')::uuid=(r->>'idempotencyKey')::uuid;
 if found then
  if old.turn_id<>tid or old.selected_place_request->>'requestDigest'<>encode(sha256(convert_to(request_bytes,'UTF8')),'hex') then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
  if place_actions_private.ask_bound_v1(tid,null) is null then raise exception 'DATA_POLICY_BLOCKED';end if;
  return place_actions_private.ask_receipt_v1(tid,old.selected_place_request);
 end if;
 -- Reject prior admission rather than attaching to already committed ordinary work.
 if exists(select 1 from public.turns where id=tid) or exists(select 1 from turn_private.text_content where turn_id=tid)
 or exists(select 1 from turn_private.service_task_turns where owner_id=u and idempotency_key=(r->>'idempotencyKey')::uuid) then raise exception 'IDEMPOTENCY_KEY_REUSE';end if;
 -- Original admission chooses and meters exactly one Task, retaining all original semantics.
 receipt:=public.submit_service_task_turn((r->>'threadId')::uuid,tid,(r->>'idempotencyKey')::uuid,(r->>'policyId')::uuid,r->>'locale',r->>'text',
 (r->'serviceTask'->>'id')::uuid,(r->'serviceTask'->>'scopeVersion')::integer,r->'serviceTask'->>'relationship',(r->'serviceTask'->>'parentTurnId')::uuid);
 if receipt->>'kind' is distinct from 'accepted' or receipt->'reused' is distinct from 'false'::jsonb then raise exception 'SERVICE_TASK_CONFLICT';end if;
 -- Current-input policy only: no additional source facts/caption enter any model prompt.
 if not exists(select 1 from turn_private.text_policies where id=(r->>'policyId')::uuid and context_mode='current_input_v1') then raise exception 'DATA_POLICY_BLOCKED';end if;
 b:=place_actions_private.ask_basis_v1(u,s,e);
 -- Match the original Native v2 receipt projection; retain its actual identities/relationship.
 receipt:=jsonb_build_object('version',2,'kind',receipt->'kind','turnId',receipt->'turnId','reused',receipt->'reused','serviceTaskId',receipt->'serviceTaskId','scopeVersion',receipt->'scopeVersion','relationship',receipt->'relationship','parentTurnId',receipt->'parentTurnId');
 p:=jsonb_build_object('schemaVersion','canonical-place-proof/1','operationId',(r->>'idempotencyKey')::uuid,'scopeKind','thread','scopeId',(r->>'threadId')::uuid,'operation',jsonb_build_object('operationId',(r->>'idempotencyKey')::uuid,'scopeKind','thread','scopeId',(r->>'threadId')::uuid,'messageId',null,'turnId',tid),'requestDigest',encode(sha256(convert_to(request_bytes,'UTF8')),'hex'),'expectation',e,'basis',b,'originalReceipt',receipt);
 insert into turn_private.grounded_turns(turn_id,owner_id,task_id,city,locale,selected_place_request) values(tid,u,(r->'serviceTask'->>'id')::uuid,b->>'city',r->>'locale',p);
 if place_actions_private.ask_bound_v1(tid,null) is null then raise exception 'DATA_POLICY_BLOCKED';end if;
 return place_actions_private.ask_receipt_v1(tid,p);
exception when raise_exception then
 if SQLERRM in('PLACE_ASK_SOURCE_UNAVAILABLE','PLACE_ASK_SELECTION_AMBIGUOUS') then
  return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','unavailable','reason',case SQLERRM when 'PLACE_ASK_SELECTION_AMBIGUOUS' then 'selection_ambiguous' else 'source_unavailable' end,'readyForProvider',false);
 end if;raise;
end $$;
revoke all on function place_actions_private.ask_submit_v1(text) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_read_v1(v jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=place_actions_private.actor_v1();g turn_private.grounded_turns%rowtype;p jsonb;current_n jsonb;begin
 if not place_actions_private.exact_v1(v,array['operationId','scopeKind','scopeId','messageId','turnId']) or not place_actions_private.ask_uuid_v1(v->'operationId') or not place_actions_private.ask_uuid_v1(v->'scopeId') or v->>'scopeKind' not in('thread','conversation') or (v->>'scopeKind'='thread' and (v->'messageId'<>'null'::jsonb or not place_actions_private.ask_uuid_v1(v->'turnId'))) or (v->>'scopeKind'='conversation' and (not place_actions_private.ask_uuid_v1(v->'messageId') or (v->'turnId'<>'null'::jsonb and not place_actions_private.ask_uuid_v1(v->'turnId')))) then raise exception 'INVALID_INPUT';end if;
 v:=jsonb_set(jsonb_set(jsonb_set(v,'{operationId}',to_jsonb((v->>'operationId')::uuid)),'{scopeId}',to_jsonb((v->>'scopeId')::uuid)),'{turnId}',coalesce(to_jsonb((v->>'turnId')::uuid),'null'::jsonb));
 select * into g from turn_private.grounded_turns where owner_id=u and selected_place_request->'operationId'=v->'operationId' and selected_place_request->'scopeKind'=v->'scopeKind' and selected_place_request->'scopeId'=v->'scopeId';
 if not found then
 if exists(select 1 from turn_private.grounded_turns where selected_place_request->'operationId'=v->'operationId')
 or exists(select 1 from turn_private.service_task_turns where idempotency_key=(v->>'operationId')::uuid and owner_id<>u)
 or exists(select 1 from public.turns where id=(v->>'turnId')::uuid and owner_id<>u) then raise exception 'FORBIDDEN';end if;
 -- Erasure deletes the sensitive proof, not the authoritative admission/fences.
 -- A missing proof is never evidence that this original operation did not commit.
 if exists(select 1 from turn_private.service_task_turns where owner_id=u and idempotency_key=(v->>'operationId')::uuid)
 or exists(select 1 from turn_private.assistant_messages where owner_id=u and idempotency_key=(v->>'operationId')::uuid)
 or exists(select 1 from public.turns where id=(v->>'turnId')::uuid and owner_id=u)
 or (v->>'turnId' is not null and turn_data_private.fenced_v1('turnIds',(v->>'turnId')::uuid)) then
  return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','unknown','operation',v,'readyForProvider',false);
 end if;
 return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','not_submitted','operation',v,'readyForProvider',false);end if;
 if g.selected_place_request->'operation' is distinct from v or not exists(select 1 from turn_private.work where turn_id=g.turn_id and session_id=(auth.jwt()->>'session_id')::uuid) then raise exception 'FORBIDDEN';end if;
 p:=place_actions_private.ask_bound_v1(g.turn_id,null);
 current_n:=case when p is null then jsonb_build_object('kind','unavailable','reason','source_unavailable') else jsonb_build_object('kind','pending') end;
 if p is not null then
  current_n:=public.read_grounded_turn(g.turn_id);
  current_n:=case when current_n->>'kind'='grounded_turn' and current_n->'result'->>'projection'='pending' then jsonb_build_object('kind','pending') when current_n->>'kind'='grounded_turn' and current_n->'result'->>'projection'='current' then jsonb_build_object('kind','grounded','turn',current_n) else jsonb_build_object('kind','unavailable','reason','source_unavailable') end;
 end if;
 return jsonb_build_object('schemaVersion','canonical-place-ask/1','kind','recovered','operation',v,'receipt',place_actions_private.ask_receipt_v1(g.turn_id,g.selected_place_request),'current',current_n,'readyForProvider',false);
end $$;
revoke all on function place_actions_private.ask_read_v1(jsonb) from public,anon,authenticated,service_role;

-- Called solely inside the existing service-role claimer after lock_turn.
create or replace function place_actions_private.ask_claim_current_v1(tid uuid) returns boolean language plpgsql security definer set search_path='' as $$
begin
 return place_actions_private.ask_root_current_v1(tid) is not null;
exception when raise_exception then return false;end $$;
revoke all on function place_actions_private.ask_claim_current_v1(uuid) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_complete_v1(tid uuid,token uuid,intent text,scope text,needs_text text,place_name text) returns jsonb language plpgsql security definer set search_path='' as $$
declare p jsonb:=place_actions_private.ask_bound_v1(tid,token);needs jsonb;q text;result jsonb;begin
 if p is null then return jsonb_build_object('kind','blocked');end if;
 if intent not in('place_address','place_opening_hours','place_address_and_hours') or scope not in('single','additional_needs') or needs_text is null or octet_length(needs_text)>12000 then raise exception 'INVALID_INPUT';end if;
 needs:=needs_text::jsonb;select input_text into q from turn_private.text_content where turn_id=tid;
 if jsonb_typeof(needs) is distinct from 'array' or jsonb_array_length(needs)>6 or (scope='additional_needs')<>(jsonb_array_length(needs)>0)
 or exists(select 1 from jsonb_array_elements(needs)x where jsonb_typeof(x) is distinct from 'string' or length(x#>>'{}') not between 1 and 240 or strpos(q,x#>>'{}')=0)
 or (select count(distinct x) from jsonb_array_elements(needs)x)<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT';end if;
 -- Canonical subject comes only from the original reviewed mapping, never place_name.
 result:=turn_private.complete_selected_grounded_work(tid,token,intent,scope,p->'basis'->>'subjectId');
 if result->>'kind'='finished' then update turn_private.grounded_turns set place_name=null,place_resolution='matched',unanswered_needs=needs where turn_id=tid;end if;
 return result;
end $$;
revoke all on function place_actions_private.ask_complete_v1(uuid,uuid,text,text,text,text) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_schema_v1() returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from pg_attribute a where a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request' and a.attnum>0 and not a.attisdropped and a.atttypid='jsonb'::regtype and not a.attnotnull and not a.atthasdef and a.attgenerated='' and a.attidentity='')
 and (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.grounded_turns'::regclass and k.conname='grounded_selected_place_request_shape') = 'CHECK (((selected_place_request IS NULL) OR place_actions_private.ask_proof_shape_v1(selected_place_request)))'
$$;
revoke all on function place_actions_private.ask_schema_v1() from public,anon,authenticated,service_role;

-- The original source tables and PK fences remain the lifecycle authority.
-- NULL on an old row must disappear before old fingerprint/export serialization.
create or replace function place_actions_private.ask_source_row_v1(rel text,v jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
begin
 if rel<>'turn_private.grounded_turns' or not(v ? 'selected_place_request') then return v;end if;
 if v->'selected_place_request'='null'::jsonb then return v-'selected_place_request';end if;
 if not place_actions_private.ask_proof_shape_v1(v->'selected_place_request') then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
 return v;
end $$;
revoke all on function place_actions_private.ask_source_row_v1(text,jsonb) from public,anon,authenticated,service_role;

create or replace function place_actions_private.ask_answer_basis_shape_v1(v jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare x jsonb;begin
 if v='null'::jsonb then return true;end if;
 if not place_actions_private.exact_v1(v,array['publications','claims']) or jsonb_typeof(v->'publications') is distinct from 'array' or jsonb_array_length(v->'publications')>50 or jsonb_typeof(v->'claims') is distinct from 'array' or jsonb_array_length(v->'claims')>6 then return false;end if;
 for x in select value from jsonb_array_elements(v->'publications') loop
  if not place_actions_private.exact_v1(x,array['factId','assertionId','revision','payloadHash']) or not place_actions_private.uuid_v1(x->'factId') or not place_actions_private.uuid_v1(x->'assertionId') or not place_actions_private.revision_v1(x->'revision') or (x->>'revision')::integer<1 or jsonb_typeof(x->'payloadHash') is distinct from 'string' or x->>'payloadHash' !~ '^[a-f0-9]{64}$' then return false;end if;
 end loop;
 for x in select value from jsonb_array_elements(v->'claims') loop
  if not place_actions_private.exact_v1(x,array['id','status','reasons','factIds']) or x->>'id' not in('place_address','opening_hours') or x->>'status' not in('covered','unavailable','unresolved_variants')
  or jsonb_typeof(x->'reasons') is distinct from 'array' or jsonb_typeof(x->'factIds') is distinct from 'array' or jsonb_array_length(x->'reasons')>8 or jsonb_array_length(x->'factIds')>50
  or exists(select 1 from jsonb_array_elements(x->'reasons')r where jsonb_typeof(r) is distinct from 'string' or r#>>'{}' not in('missing','expired','revoked','unreviewed','unresolved_variants'))
  or exists(select 1 from jsonb_array_elements(x->'factIds')f where not place_actions_private.uuid_v1(f) or not exists(select 1 from jsonb_array_elements(v->'publications')p where p->'factId'=f)) then return false;end if;
 end loop;
 return true;
end $$;
revoke all on function place_actions_private.ask_answer_basis_shape_v1(jsonb) from public,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.authorize_grounded_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; c turn_private.text_content%rowtype;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
 payload:=public.read_grounded_work(p_turn_id,p_lease_token);
 if payload->>'kind' is distinct from 'intent_input' or payload->>'policyId' is distinct from p_policy_id::text
   or payload->>'provider' is distinct from p_provider or payload->>'contextDigest' is distinct from p_context_digest then return jsonb_build_object('kind','blocked'); end if;
 select * into c from turn_private.text_content where turn_id=p_turn_id;
 insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 return jsonb_build_object('kind','authorized');
end $function$
;

CREATE OR REPLACE FUNCTION public.authorize_text_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c turn_private.text_content%rowtype;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode='planning_comparison_v1')
    then return jsonb_build_object('kind','blocked'); end if;
  if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
  select * into c from turn_private.text_content where turn_id=p_turn_id;
  if c.policy_id is distinct from p_policy_id or not exists(select 1 from turn_private.text_policies where id=p_policy_id and provider=p_provider and context_mode='current_input_v1') then return jsonb_build_object('kind','blocked'); end if;
  insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
  if not found then return jsonb_build_object('kind','blocked'); end if;
  return jsonb_build_object('kind','authorized');
end $function$
;

CREATE OR REPLACE FUNCTION public.authorize_text_task_dispatch(p_turn_id uuid, p_lease_token uuid, p_policy_id uuid, p_provider text, p_context_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare payload jsonb; c turn_private.text_content%rowtype;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  payload:=public.read_text_work(p_turn_id,p_lease_token);
  if payload->>'kind' is distinct from 'task_input' or payload->>'policyId' is distinct from p_policy_id::text
    or payload->>'provider' is distinct from p_provider or payload->>'contextDigest' is distinct from p_context_digest then return jsonb_build_object('kind','blocked'); end if;
  select * into c from turn_private.text_content where turn_id=p_turn_id;
  insert into turn_private.text_dispatches(lease_token,turn_id,consent_id,policy_id) values(p_lease_token,p_turn_id,c.consent_id,c.policy_id) on conflict do nothing;
  if not found then return jsonb_build_object('kind','blocked'); end if;
  return jsonb_build_object('kind','authorized');
end $function$
;

CREATE OR REPLACE FUNCTION public.complete_grounded_place_work(p_turn_id uuid, p_lease_token uuid, p_intent text, p_request_scope text, p_unanswered_needs text, p_place_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source_text text; city text; needs jsonb; item jsonb; selected jsonb; result jsonb; final_intent text; final_scope text;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return place_actions_private.ask_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) then return guide_private.place_complete_v1(p_turn_id,p_lease_token,p_intent,p_request_scope,p_unanswered_needs,p_place_name);end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','stale'); end if;
 if p_intent is null or p_intent not in ('place_address','place_opening_hours','place_address_and_hours')
  or p_request_scope is null or p_request_scope not in ('single','additional_needs')
  or p_place_name is null or length(p_place_name) not between 1 and 160 or p_place_name~'[[:cntrl:]]'
  or p_unanswered_needs is null or octet_length(p_unanswered_needs)>12000 then raise exception 'INVALID_INPUT'; end if;
 needs:=p_unanswered_needs::jsonb;
 if jsonb_typeof(needs) is distinct from 'array' then raise exception 'INVALID_INPUT'; end if;
 if jsonb_array_length(needs)>6 or ((p_request_scope='additional_needs')<>(jsonb_array_length(needs)>0)) then raise exception 'INVALID_INPUT'; end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select c.input_text,g.city into source_text,city from turn_private.text_content c
 join turn_private.grounded_turns g on g.turn_id=c.turn_id and g.owner_id=c.owner_id where c.turn_id=p_turn_id and g.completed_at is null;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 if strpos(source_text,p_place_name)=0 then raise exception 'INVALID_INPUT'; end if;
 for item in select value from jsonb_array_elements(needs) loop
  if jsonb_typeof(item)<>'string' or (item#>>'{}')!~'[^[:space:]]' or length(item#>>'{}')>240
   or strpos(source_text,item#>>'{}')=0 then raise exception 'INVALID_INPUT'; end if;
 end loop;
 if (select count(distinct value) from jsonb_array_elements(needs))<>jsonb_array_length(needs) then raise exception 'INVALID_INPUT'; end if;
 -- Same lock order as Ops: name barrier before publication row locks.
 perform pg_catalog.pg_advisory_xact_lock_shared(160047,1);
 begin
  selected:=knowledge_review_private.place_subject(p_place_name,city);
 exception when raise_exception then
  if SQLERRM<>'KNOWLEDGE_DISABLED' then raise; end if;
  return public.complete_grounded_work(p_turn_id,p_lease_token,'technical_failure','unknown');
 end;
 final_intent:=case selected->>'kind' when 'matched' then p_intent when 'ambiguous' then 'clarification' else 'unsupported' end;
 final_scope:=case when selected->>'kind'='matched' then p_request_scope else 'unknown' end;
 result:=turn_private.complete_selected_grounded_work(p_turn_id,p_lease_token,final_intent,final_scope,selected->>'subjectId');
 if result->>'kind'='finished' then
  update turn_private.grounded_turns set place_name=case when intent<>'technical_failure' then p_place_name end,
   place_resolution=case when intent<>'technical_failure' then selected->>'kind' end,
   unanswered_needs=case when request_scope='additional_needs' then needs else '[]'::jsonb end where turn_id=p_turn_id;
 end if;
 return result;
end $function$
;

CREATE OR REPLACE FUNCTION public.complete_text_work(p_turn_id uuid, p_lease_token uuid, p_kind text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; task uuid; task_owner uuid; capacity turn_private.service_task_capacity%rowtype; task_enforced boolean;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode='planning_intake_comparison_v2') then return jsonb_build_object('kind','stale'); end if;
  select l.task_id,l.owner_id into task,task_owner from turn_private.service_task_turns l where l.turn_id=p_turn_id;
  if task is not null then perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(task_owner::text,34)); end if;
  result:=turn_private.complete_text_work_unmetered(p_turn_id,p_lease_token,p_kind,p_text);
  if result->>'kind'<>'finished' or task is null then return result; end if;
  select * into capacity from turn_private.service_task_capacity where task_id=task for update;
  if not found then
    select capacity_enforced into task_enforced from turn_private.service_tasks where id=task;
    if task_enforced then raise exception 'SERVICE_TASK_CAPACITY_CONFLICT'; end if;
    return result; -- Existing record-only task.
  end if;
  if capacity.state<>'reserved' then return result; end if;
  if p_kind='answered' then
    -- The result was written and its terminal event committed by the wrapped function.
    -- Check the owner's current readable scope before the same transaction commits.
    if not exists(select 1 from turn_private.text_content c
      join public.turns t on t.id=c.turn_id and t.owner_id=c.owner_id and t.status='completed'
      join public.chat_threads h on h.id=c.thread_id and h.owner_id=c.owner_id and h.status='active'
      join turn_private.text_consents consent on consent.owner_id=c.owner_id and consent.policy_id=c.policy_id
        and consent.consent_id=c.consent_id and consent.revoked_at is null
      where c.turn_id=p_turn_id and c.owner_id=task_owner and c.hidden_at is null
        and c.output_kind='answered' and c.output_text=p_text and turn_private.text_policy_current(c.policy_id))
      then raise exception 'SERVICE_TASK_RESULT_UNREADABLE'; end if;
    if capacity.tier='journey_pass' and not exists(select 1 from public.storekit_grants g
      where g.environment=capacity.grant_environment and g.transaction_id=capacity.grant_transaction_id
        and g.owner_id=task_owner and g.state='active' and g.starts_at<=capacity.admitted_at
        and g.ends_at>pg_catalog.clock_timestamp()) then raise exception 'SERVICE_TASK_GRANT_UNAVAILABLE'; end if;
    update turn_private.service_task_capacity set state='settled',settled_turn_id=p_turn_id,settled_at=pg_catalog.clock_timestamp()
      where task_id=task and state='reserved';
  elsif p_kind in ('partial','blocked','technical_failure') then
    update turn_private.service_task_capacity set state='released',released_at=pg_catalog.clock_timestamp()
      where task_id=task and state='reserved';
  end if;
  return result;
end $function$
;

CREATE OR REPLACE FUNCTION conversation_data_private.schema_supported_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s record;actual_n text[];pk_n text[];foreign_n jsonb;column_specs jsonb;
begin
 if not place_actions_private.ask_schema_v1() then return false;end if;
 if not turn_private.directions_schema_members_v1() then return false;end if;
 for s in select * from conversation_data_private.sources_v1() loop
  if to_regclass(s.relation_name) is null then return false;end if;
  select array_agg(attname::text order by attnum) into actual_n from pg_attribute where attrelid=s.relation_name::regclass and attnum>0 and not attisdropped and not(attrelid='turn_private.grounded_turns'::regclass and attname='selected_place_request');
  if actual_n is distinct from s.columns_n then return false;end if;
  select array_agg(a.attname::text order by key.ordinality) into pk_n from pg_constraint c
   cross join lateral unnest(c.conkey) with ordinality key(attnum,ordinality)
   join pg_attribute a on a.attrelid=c.conrelid and a.attnum=key.attnum where c.conrelid=s.relation_name::regclass and c.contype='p';
  if pk_n is distinct from s.pk then return false;end if;
 end loop;
 select jsonb_object_agg(relation_name,cols) into column_specs from (
  select source_spec.relation_name,jsonb_agg(jsonb_build_object('name',a.attname,'type',a.atttypid::regtype::text,'notNull',a.attnotnull) order by a.attnum) cols
  from conversation_data_private.sources_v1() source_spec join pg_attribute a on a.attrelid=source_spec.relation_name::regclass
  where a.attnum>0 and not a.attisdropped and not(a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request') group by source_spec.relation_name
