_v2_model_local_journal_task_id_fkey","definition":"FOREIGN KEY (task_id) REFERENCES turn_private.service_tasks(id) ON DELETE CASCADE"},{"from":"turn_private.planning_v2_model_local_journal","to":"turn_private.planning_comparisons","name":"planning_v2_model_local_journal_turn_id_fkey","definition":"FOREIGN KEY (turn_id) REFERENCES turn_private.planning_comparisons(turn_id) ON DELETE CASCADE"},{"from":"turn_private.planning_v2_place_checkpoints","to":"auth.users","name":"planning_v2_place_checkpoints_owner_id_fkey","definition":"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"from":"turn_private.planning_v2_place_checkpoints","to":"turn_private.service_tasks","name":"planning_v2_place_checkpoints_task_id_fkey","definition":"FOREIGN KEY (task_id) REFERENCES turn_private.service_tasks(id) ON DELETE CASCADE"},{"from":"turn_private.planning_v2_place_checkpoints","to":"turn_private.planning_comparisons","name":"planning_v2_place_checkpoints_turn_id_fkey","definition":"FOREIGN KEY (turn_id) REFERENCES turn_private.planning_comparisons(turn_id) ON DELETE CASCADE"},{"from":"turn_private.planning_v2_result_claims","to":"turn_private.planning_v2_execution_runs","name":"planning_v2_result_claims_execution_id_fkey","definition":"FOREIGN KEY (execution_id) REFERENCES turn_private.planning_v2_execution_runs(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"turn_private.assistant_goals","name":"result_artifacts_goal_id_fkey","definition":"FOREIGN KEY (goal_id) REFERENCES turn_private.assistant_goals(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"turn_private.assistant_messages","name":"result_artifacts_input_message_id_fkey","definition":"FOREIGN KEY (input_message_id) REFERENCES turn_private.assistant_messages(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"auth.users","name":"result_artifacts_owner_id_fkey","definition":"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"public.trip_proposals","name":"result_artifacts_proposal_id_fkey","definition":"FOREIGN KEY (proposal_id) REFERENCES trip_proposals(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"turn_private.result_artifacts","name":"result_artifacts_source_result_id_fkey","definition":"FOREIGN KEY (source_result_id) REFERENCES turn_private.result_artifacts(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"public.turns","name":"result_artifacts_source_turn_id_fkey","definition":"FOREIGN KEY (source_turn_id) REFERENCES turns(id) ON DELETE CASCADE"},{"from":"turn_private.result_artifacts","to":"public.trips","name":"result_artifacts_trip_id_fkey","definition":"FOREIGN KEY (trip_id) REFERENCES trips(id) ON DELETE CASCADE"},{"from":"turn_private.result_events","to":"turn_private.result_artifacts","name":"result_events_artifact_id_fkey","definition":"FOREIGN KEY (artifact_id) REFERENCES turn_private.result_artifacts(id) ON DELETE CASCADE"},{"from":"turn_private.result_events","to":"auth.users","name":"result_events_owner_id_fkey","definition":"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"from":"turn_private.result_revisions","to":"turn_private.result_artifacts","name":"result_revisions_artifact_id_fkey","definition":"FOREIGN KEY (artifact_id) REFERENCES turn_private.result_artifacts(id) ON DELETE CASCADE"},{"from":"turn_private.result_revisions","to":"auth.users","name":"result_revisions_owner_id_fkey","definition":"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"from":"turn_private.result_revisions","to":"turn_private.text_content","name":"result_revisions_task_turn_id_fkey","definition":"FOREIGN KEY (task_turn_id) REFERENCES turn_private.text_content(turn_id)"},{"from":"turn_private.service_task_capacity","to":"turn_private.service_tasks","name":"service_task_capacity_task_id_fkey","definition":"FOREIGN KEY (task_id) REFERENCES turn_private.service_tasks(id)"},{"from":"turn_private.service_task_turns","to":"turn_private.text_content","name":"service_task_turns_parent_turn_id_fkey","definition":"FOREIGN KEY (parent_turn_id) REFERENCES turn_private.text_content(turn_id)"},{"from":"turn_private.service_task_turns","to":"turn_private.service_tasks","name":"service_task_turns_task_id_fkey","definition":"FOREIGN KEY (task_id) REFERENCES turn_private.service_tasks(id)"},{"from":"turn_private.service_task_turns","to":"turn_private.text_content","name":"service_task_turns_turn_id_fkey","definition":"FOREIGN KEY (turn_id) REFERENCES turn_private.text_content(turn_id) DEFERRABLE INITIALLY DEFERRED"},{"from":"turn_private.service_tasks","to":"turn_private.text_content","name":"service_tasks_goal_turn_id_fkey","definition":"FOREIGN KEY (goal_turn_id) REFERENCES turn_private.text_content(turn_id) DEFERRABLE INITIALLY DEFERRED"},{"from":"turn_private.service_tasks","to":"turn_private.text_content","name":"service_tasks_last_turn_id_fkey","definition":"FOREIGN KEY (last_turn_id) REFERENCES turn_private.text_content(turn_id) DEFERRABLE INITIALLY DEFERRED"},{"from":"turn_private.service_tasks","to":"turn_private.text_policies","name":"service_tasks_policy_id_fkey","definition":"FOREIGN KEY (policy_id) REFERENCES turn_private.text_policies(id)"},{"from":"turn_private.text_content","to":"turn_private.text_policies","name":"text_content_policy_id_fkey","definition":"FOREIGN KEY (policy_id) REFERENCES turn_private.text_policies(id)"},{"from":"turn_private.work","to":"auth.users","name":"work_owner_id_fkey","definition":"FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE"},{"from":"turn_private.work","to":"public.turns","name":"work_turn_id_fkey","definition":"FOREIGN KEY (turn_id) REFERENCES turns(id) ON DELETE CASCADE"}]'::jsonb;
end$function$
;

CREATE OR REPLACE FUNCTION conversation_data_private.source_v1(u uuid, root_kind_n text, root_id_n uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare closure_n jsonb;g jsonb;spec record;actual_n jsonb;key_n jsonb;ref record;qualified_n boolean;
 rows_n jsonb:='[]';reverse_n jsonb:='[]';authorities_n jsonb:='[]';witness_n jsonb;conflicts_n text[]:=array[]::text[];
 erase_n jsonb:=conversation_data_private.zero_counts_v1('erase');redact_n jsonb:=conversation_data_private.zero_counts_v1('redact');
 retain_n jsonb:=conversation_data_private.zero_counts_v1('retain');refs_n jsonb;trips_n uuid[]:=array[]::uuid[];memory_n uuid[]:=array[]::uuid[];
 executions uuid[]:=array[]::uuid[];turns uuid[];tasks uuid[];messages uuid[];goals uuid[];artifacts uuid[];threads uuid[];
 n integer;total_n integer:=0;reverse_total integer:=0;other_n jsonb;fingerprint_n jsonb;assistant_delivery_n jsonb;directions_n jsonb;directions_raw_bytes_n bigint:=0;relation_n text;extra_n uuid[];
begin
 -- Root ownership/policy precede source feedback, even on a capacity blocker.
 if root_kind_n='conversation' then
  select jsonb_build_array(jsonb_build_object('policyId',policy_id,'consentId',consent_id)) into authorities_n
   from turn_private.assistant_conversations where id=root_id_n and owner_id=u;
  if not found then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
  perform conversation_data_private.authorities_current_v1(u,authorities_n);
 elsif root_kind_n='thread' then
  perform 1 from public.chat_threads where id=root_id_n and owner_id=u;if not found then raise exception 'CONVERSATION_SOURCE_UNAVAILABLE';end if;
 else raise exception 'INVALID_INPUT';end if;
 closure_n:=conversation_data_private.closure_v1(u,root_kind_n,root_id_n);g:=closure_n->'graph';
 select coalesce(array_agg(value#>>'{}'),array[]::text[]) into conflicts_n from jsonb_array_elements(closure_n->'conflicts');
 if not conversation_data_private.schema_supported_v1() then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if conflicts_n @> array['SCOPE_TOO_LARGE'] then
  return jsonb_build_object('graph',g,'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',authorities_n,
   'retainedReferences','{"tripIds":[],"memoryIds":[]}'::jsonb,'conflicts',conversation_data_private.conflicts_v1(conflicts_n),'rows','[]'::jsonb,
   'sourceDigest',conversation_data_private.digest_v1(jsonb_build_array(g,conflicts_n,authorities_n)::text));
 end if;
 turns:=privacy_private.linked_delete_array_v1(g->'turnIds');tasks:=privacy_private.linked_delete_array_v1(g->'taskIds');
 messages:=privacy_private.linked_delete_array_v1(g->'messageIds');goals:=privacy_private.linked_delete_array_v1(g->'goalIds');
 artifacts:=privacy_private.linked_delete_array_v1(g->'artifactIds');threads:=privacy_private.linked_delete_array_v1(g->'threadIds');
 if root_kind_n='thread' and (cardinality(threads)<>1 or threads[1]<>root_id_n) then conflicts_n:=conflicts_n||array['CROSS_SCOPE_REFERENCE'];end if;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into executions from turn_private.planning_v2_execution_runs
  where owner_id=u and (turn_id=any(turns) or task_id=any(tasks));
 for spec in select * from conversation_data_private.sources_v1() order by relation_name collate "C" loop
  n:=0;
  for actual_n in execute format('select to_jsonb(actual) from %s actual where conversation_data_private.related_v1(%L,to_jsonb(actual),$1,$2) order by conversation_data_private.row_key_v1(to_jsonb(actual),$3)::text collate "C" limit 10001',spec.relation_name,spec.relation_name)
   using g,executions,spec.pk loop
   actual_n:=place_actions_private.ask_source_row_v1(spec.relation_name,actual_n);
   n:=n+1;total_n:=total_n+1;
   if n>10000 or total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   key_n:=conversation_data_private.row_key_v1(actual_n,spec.pk);
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(actual_n::text);
   rows_n:=rows_n||jsonb_build_array(jsonb_build_object('table',spec.relation_name,'pk',key_n,'digest',conversation_data_private.digest_v1(actual_n::text),'effect',spec.effect,'countKey',spec.count_key));
   if spec.has_owner then qualified_n:=actual_n->>'owner_id'=u::text;
   elsif spec.relation_name='public.model_budget_attempts' then
    qualified_n:=exists(select 1 from turn_private.service_tasks t join public.model_budget_scopes b on b.id=(actual_n->>'scope_id')::uuid where t.id=(actual_n->>'task_id')::uuid and t.owner_id=u and b.owner_id=u);
   elsif spec.relation_name='turn_private.text_dispatches' then
    qualified_n:=exists(select 1 from turn_private.text_content t where t.turn_id=(actual_n->>'turn_id')::uuid and t.owner_id=u);
   else qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs e where e.id=(actual_n->>'execution_id')::uuid and e.owner_id=u);end if;
   if not qualified_n then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];continue;end if;
   if spec.effect='erase' then erase_n:=jsonb_set(erase_n,array[spec.count_key],to_jsonb((erase_n->>spec.count_key)::integer+1));
   elsif spec.effect='redact' then redact_n:=jsonb_set(redact_n,array[spec.count_key],to_jsonb((redact_n->>spec.count_key)::integer+1));
   else retain_n:=jsonb_set(retain_n,array[spec.count_key],to_jsonb((retain_n->>spec.count_key)::integer+1));end if;
   if actual_n->>'policy_id' is not null and actual_n->>'consent_id' is not null then
    authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',actual_n->'policy_id','consentId',actual_n->'consent_id'));
   end if;
   if actual_n->>'planning_policy_id' is not null and actual_n->>'planning_consent_id' is not null then
    authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',actual_n->'planning_policy_id','consentId',actual_n->'planning_consent_id'));
   end if;
   -- Retained historical link receipts do not seed another deleted conversation.
   if spec.count_key<>'goalTripReceipts' then
    for ref in select * from conversation_data_private.json_references_v1(actual_n) loop
     if not(g->ref.kind ? ref.entity_id::text) then conflicts_n:=conflicts_n||array['CROSS_SCOPE_REFERENCE'];end if;
    end loop;
   end if;
   if spec.count_key='turns' then
    if actual_n->>'status'='proposal_ready' then conflicts_n:=conflicts_n||array['PROPOSAL_REFERENCE'];
    elsif actual_n->>'status' not in('completed','unavailable','failed','cancelled') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
   elsif spec.count_key='work' and actual_n->>'state' not in('completed','failed','cancelled') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='assistJobs' and actual_n->>'status' in('queued','running') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='planning' and actual_n->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='capacity' and actual_n->>'state'='reserved' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='budgetAttempts' and actual_n->>'status' not in('settled','released') then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='checkpoints' and actual_n->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='attemptBindings' and actual_n->>'unknown_at' is not null then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='collectorOrigins' and (actual_n->>'unknown_at' is not null or actual_n->>'attempted_at' is not null and actual_n->>'response_buffered_at' is null) then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='resultClaims' and actual_n->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='localJournals' and (actual_n->>'unknown_at' is not null or actual_n->>'phase'<>'response_recorded'
     or not exists(select 1 from turn_private.planning_v2_completed_receipts c where c.turn_id=(actual_n->>'turn_id')::uuid and c.owner_id=u)) then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];
   elsif spec.count_key='callWindows' and (actual_n->>'calls')::integer>0
     and not exists(select 1 from turn_private.planning_v2_completion_proofs p where p.execution_id=(actual_n->>'execution_id')::uuid and p.owner_id=u) then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
   if actual_n->>'proposal_id' is not null or actual_n->'content'->>'schemaVersion' in('proposal_preview/1','change-proposal/1') then conflicts_n:=conflicts_n||array['PROPOSAL_REFERENCE'];end if;
   if actual_n->>'trip_id' is not null then trips_n:=conversation_data_private.union_ids_v1(trips_n||array[(actual_n->>'trip_id')::uuid]);end if;
   if actual_n->>'memory_id' is not null then memory_n:=conversation_data_private.union_ids_v1(memory_n||array[(actual_n->>'memory_id')::uuid]);end if;
   if jsonb_typeof(actual_n->'memory_basis')='array' then
    select array_agg(coalesce(entry->>'memoryId',entry->>'id')::uuid) into extra_n from jsonb_array_elements(actual_n->'memory_basis') entry where notification_private.uuid(coalesce(entry->'memoryId',entry->'id')) is true;
    memory_n:=conversation_data_private.union_ids_v1(memory_n||coalesce(extra_n,array[]::uuid[]));
   end if;
  end loop;
  if conflicts_n @> array['SCOPE_TOO_LARGE'] then exit;end if;
 end loop;
 redact_n:=jsonb_set(redact_n,'{taskDigests}',to_jsonb(cardinality(tasks)));
 authorities_n:=conversation_data_private.authorities_union_v1(authorities_n);
 if jsonb_array_length(authorities_n)>100 then raise exception 'CONVERSATION_CAPACITY';end if;
 witness_n:=conversation_data_private.authorities_current_v1(u,authorities_n);
 other_n:=conversation_data_private.impact_inventory_v1(g);
 if other_n->'rows'<>'[]'::jsonb then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if other_n->'overflow'='true'::jsonb then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 reverse_n:=reverse_n||(other_n->'rows');reverse_total:=jsonb_array_length(reverse_n);
 -- Reverse JSON references in all actual application JSON tables. Known
 -- domain matches are blockers; any unregistered stored relation is unsupported.
 for relation_n in select distinct (n.nspname||'.'||c.relname) collate "C" from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid
  where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','conversation_data_private')
  and not(n.nspname='knowledge_review_private' and c.relname like 'source_impact_%')
  and a.attnum>0 and not a.attisdropped and (a.atttypid in('jsonb'::regtype,'json'::regtype) or conversation_data_private.reference_kind_v1(a.attname::text) is not null or n.nspname in('notification_private','service_brief_private','readiness_private','guide_private','scoped_edit_private'))
  and not exists(select 1 from conversation_data_private.sources_v1() s where s.relation_name=n.nspname||'.'||c.relname)
  -- Exact delivery relations covered by private witness and catalog pins.
  and n.nspname||'.'||c.relname not in ('turn_private.assistant_event_heads_v1','turn_private.assistant_events_v1','turn_private.assistant_directions_intakes_v1','turn_private.directions_result_sources_v1','turn_private.directions_operations_v1')
  order by 1 loop
  n:=0;
  for actual_n in execute format('select to_jsonb(actual) from %s actual where conversation_data_private.related_v1(%L,conversation_data_private.documents_v1(%L,to_jsonb(actual)),$1,$2) order by to_jsonb(actual)::text collate "C" limit 10001',relation_n,relation_n,relation_n) using g,executions loop
   actual_n:=place_actions_private.ask_source_row_v1(relation_n,actual_n);
   n:=n+1;reverse_total:=reverse_total+1;
   if n>10000 or reverse_total+total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(actual_n::text);
   reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',relation_n,'digest',conversation_data_private.digest_v1(actual_n::text)));
   conflicts_n:=conflicts_n||case
    when relation_n like 'readiness_private.%' then 'READINESS_REFERENCE'
    when relation_n like 'guide_private.%' then 'GUIDE_REFERENCE'
    when relation_n like 'scoped_edit_private.%' then 'SCOPED_EDIT_REFERENCE'
    when relation_n like 'notification_private.%' then 'NOTIFICATION_REFERENCE'
    when relation_n like 'service_brief_private.%' then 'BRIEF_REFERENCE'
    else 'SOURCE_UNSUPPORTED' end;
  end loop;
 end loop;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into trips_n from public.trips where id=any(trips_n) and owner_id=u;
 select coalesce(array_agg(id order by id),array[]::uuid[]) into memory_n from public.memory_profiles where id=any(memory_n) and owner_id=u;
 refs_n:=jsonb_build_object('tripIds',trips_n,'memoryIds',memory_n);
 for relation_n in select unnest(array['export_private.core_jobs_v1','export_private.core_artifacts_v1']) loop
  n:=0;
  for actual_n in execute format('select to_jsonb(actual) from %s actual where owner_id=$1 order by request_id limit 10001',relation_n) using u loop
   actual_n:=place_actions_private.ask_source_row_v1(relation_n,actual_n);
   n:=n+1;reverse_total:=reverse_total+1;
   if n>10000 or reverse_total+total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   directions_raw_bytes_n:=directions_raw_bytes_n+octet_length(actual_n::text);
   reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',relation_n,'digest',conversation_data_private.digest_v1(actual_n::text)));
  end loop;
 end loop;
 if exists(select 1 from export_private.core_artifacts_v1 where owner_id=u)
  or exists(select 1 from export_private.core_jobs_v1 where owner_id=u and (state in('queued','running') or lease_expires_at>clock_timestamp())) then conflicts_n:=conflicts_n||array['CORE_EXPORT_COPY'];end if;
 if exists(select 1 from privacy_private.trip_deletions where owner_id=u and trip_id=any(trips_n) and state='queued')
  or exists(select 1 from privacy_private.linked_delete_fences_v1 f where exists(select 1 from jsonb_each(g) group_n where group_n.value ? f.entity_id::text))
  or exists(select 1 from privacy_private.memory_delete_jobs_v1 j join privacy_private.memory_delete_plans_v1 plan on plan.id=j.plan_id where j.owner_id=u and j.state='queued' and (privacy_private.memory_delete_ids_v1(plan.selection)&&memory_n or privacy_private.linked_delete_array_v1(plan.selection->'artifactIds')&&artifacts or privacy_private.linked_delete_array_v1(plan.selection->'generatedTurnIds')&&turns)) then conflicts_n:=conflicts_n||array['OTHER_DELETE_PENDING'];end if;
 if exists(select 1 from turn_private.result_revisions r where not r.artifact_id=any(artifacts)
  and exists(select 1 from conversation_data_private.json_references_v1(r.content) stored_ref where g->stored_ref.kind ? stored_ref.entity_id::text))
  or exists(select 1 from turn_private.assistant_message_source_receipts r where not r.message_id=any(messages)
   and (conversation_data_private.related_v1('reverse',r.input_sources,g,executions) or conversation_data_private.related_v1('reverse',r.captured_sources,g,executions))) then conflicts_n:=conflicts_n||array['CROSS_SCOPE_REFERENCE'];end if;
 assistant_delivery_n:=turn_private.assistant_delivery_source_v1(u,g);
 directions_n:=turn_private.directions_source_witness_v1(u,'conversation',g);
 fingerprint_n:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'graph',g,'rows',rows_n,'reverse',reverse_n,'sourceAuthorities',authorities_n,'authorityWitness',witness_n,
  'trips',(select coalesce(jsonb_agg(to_jsonb(actual) order by id),'[]') from public.trips actual where id=any(trips_n) and owner_id=u),
  'memory',(select coalesce(jsonb_agg(to_jsonb(actual) order by id),'[]') from public.memory_profiles actual where id=any(memory_n) and owner_id=u),
  'conflicts',conversation_data_private.conflicts_v1(conflicts_n));
 if (directions_n->>'rowCount')::integer+jsonb_array_length(assistant_delivery_n->'rows')+total_n+reverse_total+jsonb_array_length(witness_n)+cardinality(trips_n)+cardinality(memory_n)>4100 or directions_raw_bytes_n+(directions_n->>'bytes')::bigint>1000000 or octet_length(fingerprint_n::text)>1000000 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 if conflicts_n @> array['SCOPE_TOO_LARGE'] then
  g:=jsonb_set(conversation_data_private.empty_graph_v1(),array[case root_kind_n when 'conversation' then 'conversationIds' else 'threadIds' end],to_jsonb(array[root_id_n]));
  erase_n:=conversation_data_private.zero_counts_v1('erase');redact_n:=conversation_data_private.zero_counts_v1('redact');retain_n:=conversation_data_private.zero_counts_v1('retain');rows_n:='[]';refs_n:='{"tripIds":[],"memoryIds":[]}';
 end if;
 return jsonb_build_object('graph',g,'eraseCounts',erase_n,'redactCounts',redact_n,'retainCounts',retain_n,'sourceAuthorities',authorities_n,'retainedReferences',refs_n,
  'conflicts',conversation_data_private.conflicts_v1(conflicts_n),'rows',rows_n,'directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'sourceDigest',conversation_data_private.digest_v1(fingerprint_n::text));
end$function$
;

CREATE OR REPLACE FUNCTION export_private.core_turn_page_v1(v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j export_private.core_jobs_v1;l uuid;g integer;src jsonb;page jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'FORBIDDEN';end if;
 if notification_private.exact(v,array['requestId','leaseId','generation','section','cursor','limit']) is not true or notification_private.uuid(v->'requestId') is not true or notification_private.uuid(v->'leaseId') is not true or export_private.profile_natural_v1(v->'generation',3) is not true or v->'generation'='0' or v->>'section' is distinct from 'snapshot' or v->'cursor' is distinct from 'null'::jsonb or export_private.profile_natural_v1(v->'limit',100) is not true or v->'limit'='0' then raise exception 'INVALID_INPUT';end if;
 l:=(v->>'leaseId')::uuid;g:=(v->>'generation')::integer;j:=export_private.lock_job_v1((v->>'requestId')::uuid,true);
 if j.request_id is null or export_private.live_lease_v1(j,l,g) is not true then return jsonb_build_object('kind','unavailable');end if;
 if (v->>'limit')::integer>(j.policy_snapshot->>'page_size')::integer then raise exception 'INVALID_INPUT';end if;
 src:=turn_data_private.export_source_v1(j.owner_id);
 page:=jsonb_build_object('schemaVersion',case when exists(select 1 from jsonb_array_elements(src->'snapshot'->'sources') selected_group cross join lateral jsonb_array_elements(selected_group->'rows') selected_row where selected_group->>'relation'='turn_private.grounded_turns' and selected_row ? 'selected_place_request') then 'turn-core-export/3' else 'turn-core-export/1' end,'section','snapshot','sourceDigest',src->'sourceDigest','items',jsonb_build_array(src->'snapshot'),'hasMore',false,'nextCursor',null,'sectionComplete',true);
 if octet_length(notification_private.canonical(page))>1000000 then raise exception 'TURN_CAPACITY';end if;
 if export_private.live_lease_v1(j,l,g) is not true then return jsonb_build_object('kind','unavailable');end if;return page;
end$function$
;

CREATE OR REPLACE FUNCTION public.grounded_ai_assist_work_v1(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u uuid; s uuid; action text; tid uuid;
  g turn_private.grounded_turns%rowtype;
  job turn_private.grounded_ai_assist_jobs%rowtype;
  result jsonb;
begin
  if p_input->>'action'='selected_submit' then
    if not place_actions_private.exact_v1(p_input,array['action','requestBytes']) or jsonb_typeof(p_input->'requestBytes') is distinct from 'string' then raise exception 'INVALID_INPUT';end if;
    return place_actions_private.ask_submit_v1(p_input->>'requestBytes');
  elsif p_input->>'action'='selected_read' then
    if not place_actions_private.exact_v1(p_input,array['action','operation']) then raise exception 'INVALID_INPUT';end if;
    return place_actions_private.ask_read_v1(p_input->'operation');
  end if;
  if p_input is null or jsonb_typeof(p_input) <> 'object' then raise exception 'INVALID_INPUT'; end if;
  action := p_input->>'action';
  if action is null or action not in ('ensure', 'complete') then raise exception 'INVALID_INPUT'; end if;

  if action = 'ensure' then
    if (select array_agg(key order by key) from jsonb_object_keys(p_input) key) <> array['action','turnId']
      or jsonb_typeof(p_input->'turnId') is distinct from 'string'
      or (p_input->>'turnId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      then raise exception 'INVALID_INPUT'; end if;
    tid := (p_input->>'turnId')::uuid;
    u := turn_private.text_owner();
    s := (auth.jwt()->>'session_id')::uuid;
    if not turn_private.lock_turn(tid, u, s) then return jsonb_build_object('kind', 'unavailable'); end if;

    select * into g from turn_private.grounded_turns where turn_id = tid and owner_id = u;
    if not found or g.original_outcome is distinct from 'blocked' then return jsonb_build_object('kind', 'not_applicable'); end if;
    if public.read_grounded_ai_assist_context_v1(tid)->>'kind' is distinct from 'context' then return jsonb_build_object('kind','unavailable'); end if;

    select * into job from turn_private.grounded_ai_assist_jobs where turn_id = tid for update;
    if not found then
      insert into turn_private.grounded_ai_assist_jobs(turn_id, owner_id, status, started_at)
        values (tid, u, 'running', clock_timestamp())
        returning * into job;
      return jsonb_build_object('kind', 'claimed', 'jobId', job.id, 'claimToken', job.claim_token);
    end if;
    if job.owner_id <> u then return jsonb_build_object('kind', 'unavailable'); end if;
    if job.status in ('succeeded', 'failed', 'cancelled') then
      return jsonb_build_object('kind', 'done', 'jobId', job.id, 'status', job.status, 'outcome', job.outcome, 'errorCode', job.error_code);
    end if;
    if job.status = 'running' and job.started_at > clock_timestamp() - interval '2 minutes' then
      return jsonb_build_object('kind', 'pending', 'jobId', job.id);
    end if;
    -- Either still 'queued' (should not normally happen, since insert above
    -- starts a job 'running' directly) or a 'running' claim old enough to
    -- treat as an abandoned attempt. A fresh claim_token fences off any late
    -- completion from whoever held the job before this reclaim.
    update turn_private.grounded_ai_assist_jobs
      set status = 'running', started_at = clock_timestamp(), finished_at = null, outcome = null, error_code = null, claim_token = gen_random_uuid()
      where id = job.id
      returning * into job;
    return jsonb_build_object('kind', 'claimed', 'jobId', job.id, 'claimToken', job.claim_token);
  end if;

  -- complete
  if (select array_agg(key order by key) from jsonb_object_keys(p_input) key) <> array['action','claimToken','jobId','outcome']
    or jsonb_typeof(p_input->'jobId') is distinct from 'string'
    or (p_input->>'jobId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or jsonb_typeof(p_input->'claimToken') is distinct from 'string'
    or (p_input->>'claimToken') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or jsonb_typeof(p_input->'outcome') <> 'object' or p_input->'outcome'->>'kind' not in ('succeeded', 'failed')
    then raise exception 'INVALID_INPUT'; end if;

  u := turn_private.text_owner();
  -- Resolve and authorize before taking the job row lock: context/root
  -- locks precede job locks, matching ensure. Re-read the immutable identity
  -- and token state under the row lock before any completion write.
  select * into job from turn_private.grounded_ai_assist_jobs where id = (p_input->>'jobId')::uuid;
  if not found then raise exception 'OPS_NOT_FOUND'; end if;
  if job.owner_id <> u then raise exception 'UNAUTHENTICATED'; end if;
  if public.read_grounded_ai_assist_context_v1(job.turn_id)->>'kind' is distinct from 'context' then return jsonb_build_object('kind','unavailable'); end if;
  select * into job from turn_private.grounded_ai_assist_jobs where id = (p_input->>'jobId')::uuid for update;
  if not found then raise exception 'OPS_NOT_FOUND'; end if;
  if job.owner_id <> u then raise exception 'UNAUTHENTICATED'; end if;
  if job.status <> 'running' then raise exception 'OPS_CONFLICT'; end if;
  if (p_input->>'claimToken')::uuid is distinct from job.claim_token then raise exception 'OPS_CONFLICT'; end if;

  if p_input->'outcome'->>'kind' = 'succeeded' then
    if jsonb_typeof(p_input->'outcome'->'result') <> 'object' then raise exception 'INVALID_INPUT'; end if;
    update turn_private.grounded_ai_assist_jobs
      set status = 'succeeded', finished_at = clock_timestamp(), outcome = p_input->'outcome'->'result'
      where id = job.id;
    result := jsonb_build_object('kind', 'succeeded', 'jobId', job.id);
  else
    if length(btrim(p_input->'outcome'->>'errorCode')) not between 1 and 60 then raise exception 'INVALID_INPUT'; end if;
    update turn_private.grounded_ai_assist_jobs
      set status = 'failed', finished_at = clock_timestamp(), error_code = p_input->'outcome'->>'errorCode'
      where id = job.id;
    result := jsonb_build_object('kind', 'failed', 'jobId', job.id);
  end if;
  return result;
end $function$
;

CREATE OR REPLACE FUNCTION profile_data_private.schema_v1()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;actual jsonb;expected jsonb;fk jsonb;names text[]:=array['public.user_profiles','turn_private.assistant_directions_intakes_v1','turn_private.directions_operations_v1','turn_private.directions_result_sources_v1'];begin
 if not place_actions_private.ask_schema_v1() then return false;end if;

 -- QA v1 accepts exactly the authored extensions; every other schema member stays in the original digest.
 if (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check') is distinct from 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text, ''qa_session_history_v1''::text])))' then return false;end if;
 if (select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check') is distinct from 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text, ''qa_followup''::text, ''qa_correction''::text])))' then return false;end if;
 if not turn_private.directions_schema_members_v1() then return false;end if;
 -- Exact approved full application delta; unknown unlinked application tables
 -- also fail closed. Managed namespace checks remain the original fixed helper.
 if not result_data_private.infrastructure_supported_v1() or profile_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and not(a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request')),'constraints',(select jsonb_agg(case when k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check' then 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text])))' when k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check' then 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text])))' else pg_get_constraintdef(k.oid) end order by k.conname) from pg_constraint k where k.conrelid=c.oid and not(k.conrelid='turn_private.grounded_turns'::regclass and k.conname='grounded_selected_place_request_shape'))) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)<> '0ec0fcfc206909a38756272a65a877c6ab857c00fd114178d135837da951c73a' then return false;end if;
 for r in select * from profile_data_private.sources_v1() loop names:=names||r.relation_name;end loop;
 expected:='{"public.turns":{"columns":[["id","uuid",true],["owner_id","uuid",true],["trip_id","uuid",false],["status","text",true],["created_at","timestamp with time zone",true],["thread_id","uuid",false],["updated_at","timestamp with time zone",true]],"constraints":["UNIQUE (id, owner_id)","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (id)","CHECK ((status = ANY (ARRAY[''accepted''::text, ''planning''::text, ''retrieving''::text, ''generating''::text, ''validating''::text, ''completed''::text, ''proposal_ready''::text, ''unavailable''::text, ''failed''::text, ''cancelled''::text])))","FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE","FOREIGN KEY (trip_id) REFERENCES public.trips(id) ON DELETE SET NULL"]},"turn_private.work":{"columns":[["turn_id","uuid",true],["owner_id","uuid",true],["session_id","uuid",true],["state","text",true],["attempt","integer",true],["max_attempts","integer",true],["lease_ms","integer",true],["lease_token","uuid",false],["expires_at","timestamp with time zone",false],["created_at","timestamp with time zone",true],["execution_mode","text",true]],"constraints":["CHECK (((attempt >= 0) AND (attempt <= 5)))","CHECK (((state = ''leased''::text) = ((lease_token IS NOT NULL) AND (expires_at IS NOT NULL))))","CHECK (((state = ''leased''::text) OR ((lease_token IS NULL) AND (expires_at IS NULL))))","CHECK ((execution_mode = ANY (ARRAY[''text''::text, ''planning_comparison_v1''::text, ''planning_intake_comparison_v2''::text, ''scoped_trip_edit_v1''::text, ''travel_directions_v1''::text])))","CHECK (((lease_ms >= 1000) AND (lease_ms <= 300000)))","CHECK (((max_attempts >= 1) AND (max_attempts <= 5)))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","PRIMARY KEY (turn_id)","CHECK ((state = ANY (ARRAY[''queued''::text, ''leased''::text, ''completed''::text, ''failed''::text, ''cancelled''::text, ''quarantined''::text])))","FOREIGN KEY (turn_id) REFERENCES public.turns(id) ON DELETE CASCADE"]},"public.user_profiles":{"columns":[["owner_id","uuid",true],["display_name","text",false],["travel_pace","text",true],["locale","text",true],["currency","text",true],["distance_unit","text",true],["temperature_unit","text",true],["default_departure_time","time without time zone",true],["created_at","timestamp with time zone",true],["updated_at","timestamp with time zone",true],["pace_revision","bigint",true],["pace_state","text",true],["pace_notice","text",false],["pace_operation","uuid",false],["pace_request","jsonb",false],["pace_undo","jsonb",false],["profile_revision","bigint",true],["profile_saved_fields","jsonb",true]],"constraints":["CHECK (((pace_state <> ALL (ARRAY[''explicit''::text, ''paused''::text])) OR (pace_notice IS NOT NULL)))","CHECK ((currency = ANY (ARRAY[''CNY''::text, ''USD''::text, ''EUR''::text, ''RUB''::text, ''SAR''::text])))","CHECK (((display_name IS NULL) OR ((char_length(display_name) >= 1) AND (char_length(display_name) <= 80))))","CHECK ((distance_unit = ANY (ARRAY[''kilometre''::text, ''mile''::text])))","CHECK ((locale = ANY (ARRAY[''zh''::text, ''en''::text, ''es''::text, ''ru''::text, ''ar''::text])))","FOREIGN KEY (owner_id) REFERENCES auth.users(id) ON DELETE CASCADE","CHECK (((pace_notice IS NULL) OR (pace_notice = ''local-planning-cross-trip-v1''::text)))","CHECK (((pace_revision >= 0) AND (pace_revision <= ''9007199254740990''::bigint)))","CHECK ((pace_state = ANY (ARRAY[''unset''::text, ''explicit''::text, ''paused''::text, ''revoked''::text])))","PRIMARY KEY (owner_id)","CHECK (((profile_revision >= 0) AND (profile_revision <= ''9007199254740990''::bigint)))","CHECK ((temperature_unit = ANY (ARRAY[''celsius''::text, ''fahrenheit''::text])))","CHECK ((travel_pace = ANY (ARRAY[''relaxed''::text, ''balanced''::text, ''packed''::text])))"]},"public.privacy_requests":{"columns":[["id","uuid",true],["owner_id","uuid",true],["action","text",true],["scope_version","text",true],["status","text",true],["exe