CREATE OR REPLACE FUNCTION public.read_grounded_ai_assist_context_v1(p_turn_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=turn_private.text_owner(); g turn_private.grounded_turns%rowtype; c turn_private.text_content%rowtype; qualified jsonb;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,null) is null then return jsonb_build_object('kind','unavailable');end if;
  if not turn_private.lock_turn(p_turn_id,u,(auth.jwt()->>'session_id')::uuid) then return jsonb_build_object('kind','unavailable'); end if;
  select * into c from turn_private.text_content where turn_id=p_turn_id and owner_id=u and hidden_at is null;
  if not found or not turn_private.text_policy_current(c.policy_id) then return jsonb_build_object('kind','unavailable'); end if;
  select * into g from turn_private.grounded_turns where turn_id=p_turn_id and owner_id=u;
  if not found or g.completed_at is null then return jsonb_build_object('kind','unavailable'); end if;
  -- The one real gate: AI-assisted search is offered only as a supplement
  -- when the authoritative structured answer genuinely found nothing for
  -- every required claim. It is never offered as a bypass when the
  -- resolver's own judgement was answered or partial.
  if g.original_outcome <> 'blocked' then return jsonb_build_object('kind','not_applicable'); end if;
  -- Reuse the original current owner/session/consent/source read and its
  -- existing Guide-marked binding guard; do not mint a subject from a name,
  -- a client canonical ID, or model output at this integration point.
  if g.intent in ('place_address','place_opening_hours','place_address_and_hours') then
    qualified := public.read_grounded_turn(p_turn_id);
    if qualified->>'kind' is distinct from 'grounded_turn'
      or qualified->>'turnId' is distinct from p_turn_id::text
      or qualified->>'locale' is distinct from c.locale
      or qualified->>'input' is distinct from c.input_text
      or qualified->'result'->>'projection' is distinct from 'current'
      or qualified->'result'->>'city' is distinct from g.city
      or qualified->'result'->>'intent' is distinct from g.intent
      or qualified->'result'->>'originalOutcome' is distinct from 'blocked'
      or qualified->'result'->>'placeResolution' is distinct from 'matched'
      or qualified->'result'->>'placeSubjectId' is distinct from g.place_subject_id
      or g.place_subject_id is null then return jsonb_build_object('kind','unavailable'); end if;
  end if;
  return jsonb_build_object('kind','context','turnId',c.turn_id,'city',g.city,'locale',c.locale,
    'intent',g.intent,'inputText',c.input_text,'placeName',g.place_name,
    'placeSubjectId',g.place_subject_id,'placeResolution',g.place_resolution);
end $function$
;

CREATE OR REPLACE FUNCTION public.read_grounded_turn(p_turn_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=turn_private.text_owner(); g turn_private.grounded_turns%rowtype; c turn_private.text_content%rowtype;
 s turn_private.service_tasks%rowtype; l turn_private.service_task_turns%rowtype; answer jsonb; failure text; projection text; effective_status text; work_state text;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,null) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,null) is null then return jsonb_build_object('kind','blocked');end if;
 if not turn_private.lock_turn(p_turn_id,u,(auth.jwt()->>'session_id')::uuid) then return jsonb_build_object('kind','unavailable'); end if;
 select * into c from turn_private.text_content where turn_id=p_turn_id and owner_id=u and hidden_at is null;
 if not found or not turn_private.text_policy_current(c.policy_id) then return jsonb_build_object('kind','unavailable'); end if;
 perform 1 from turn_private.text_consents where owner_id=u and policy_id=c.policy_id and consent_id=c.consent_id and revoked_at is null for share;
 if not found then return jsonb_build_object('kind','unavailable'); end if;
 select * into g from turn_private.grounded_turns where turn_id=p_turn_id and owner_id=u;
 if not found then return jsonb_build_object('kind','unavailable'); end if;
 select * into s from turn_private.service_tasks where id=g.task_id and owner_id=u and policy_id=c.policy_id and consent_id=c.consent_id and (expected_result='reviewed_answer' or (expected_result='text_answer' and g.selected_place_request is not null));
 if not found or not exists(select 1 from turn_private.text_content x join public.turns t on t.id=x.turn_id and t.owner_id=u where x.turn_id=s.goal_turn_id and x.hidden_at is null) then return jsonb_build_object('kind','unavailable'); end if;
 select * into l from turn_private.service_task_turns where turn_id=p_turn_id and task_id=s.id and owner_id=u;
 if not found then return jsonb_build_object('kind','unavailable'); end if;
 select status into effective_status from public.turns where id=c.turn_id and owner_id=u;
 if g.completed_at is null and effective_status in ('accepted','planning','retrieving','generating','validating') then
  select state into work_state from turn_private.work where turn_id=c.turn_id and owner_id=u;
  if work_state='cancelled' then effective_status:='cancelled';
  elsif work_state in ('failed','quarantined') then effective_status:='failed'; end if;
 end if;
 projection:=case when g.completed_at is null then 'pending' else 'current' end;
 if knowledge_review_private.question_definition(g.intent) is not null then
  begin
   answer:=knowledge_review_private.resolve_question(knowledge_review_private.selected_question_input(g.intent,g.city,g.locale,g.place_subject_id),g.basis)-'_basis';
  exception when raise_exception then
   get stacked diagnostics failure=MESSAGE_TEXT;
   if failure not in ('KNOWLEDGE_DISABLED','KNOWLEDGE_CAPACITY','KNOWLEDGE_SNAPSHOT_CHANGED') then raise; end if;
   projection:='unavailable';answer:=null;
  end;
 end if;
 return jsonb_build_object('kind','grounded_turn','schemaVersion','grounded-turn/1','turnId',c.turn_id,'threadId',c.thread_id,
  'locale',c.locale,'input',c.input_text,'outcome',c.output_kind,'output',c.output_text,'status',effective_status,'createdAt',c.created_at,
  'serviceTaskId',s.id,'scopeVersion',s.scope_version,'relationship',l.relationship,'parentTurnId',l.parent_turn_id,
  'result',jsonb_build_object('type','reviewed_answer','city',g.city,'intent',g.intent,'requestScope',g.request_scope,'unansweredNeeds',g.unanswered_needs,'placeSubjectId',g.place_subject_id,'placeName',g.place_name,'placeResolution',g.place_resolution,
    'originalOutcome',g.original_outcome,'completedAt',g.completed_at,'projection',projection,'knowledge',answer));
end $function$
;

CREATE OR REPLACE FUNCTION public.read_grounded_work(p_turn_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c turn_private.text_content%rowtype; p turn_private.text_policies%rowtype; g turn_private.grounded_turns%rowtype; payload jsonb;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) and place_actions_private.ask_bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
 if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) and guide_private.bound_v1(p_turn_id,p_lease_token) is null then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
 if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
 select * into c from turn_private.text_content where turn_id=p_turn_id;
 select * into p from turn_private.text_policies where id=c.policy_id and (context_mode='knowledge_intent_v1' or (context_mode='current_input_v1' and exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null)));
 if not found then return jsonb_build_object('kind','blocked'); end if;
 select * into g from turn_private.grounded_turns where turn_id=c.turn_id and owner_id=c.owner_id and locale=c.locale;
 if not found then return jsonb_build_object('kind','blocked'); end if;
 payload:=jsonb_build_object('kind','intent_input','text',c.input_text,'locale',c.locale,'policyId',p.id,'provider',p.provider,'endpoint',p.endpoint);
 payload:=payload||jsonb_build_object('contextDigest',encode(pg_catalog.sha256(convert_to(jsonb_build_array(payload,g.city,g.scope_version)::text,'UTF8')),'hex')); if exists(select 1 from guide_private.bindings_v1 where turn_id=p_turn_id) then return guide_private.input_v1(p_turn_id,p_lease_token,payload);end if;return payload;
end $function$
;

CREATE OR REPLACE FUNCTION public.read_text_work(p_turn_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c turn_private.text_content%rowtype; p turn_private.text_policies%rowtype; history jsonb; payload jsonb;
begin
 if exists(select 1 from turn_private.grounded_turns where turn_id=p_turn_id and selected_place_request is not null) then return jsonb_build_object('kind','blocked');end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode in('planning_intake_comparison_v2','scoped_trip_edit_v1','travel_directions_v1')) then return jsonb_build_object('kind','blocked'); end if;
  if exists(select 1 from turn_private.work where turn_id=p_turn_id and execution_mode='planning_comparison_v1')
    then return jsonb_build_object('kind','blocked'); end if;
  if not turn_private.lock_text_work(p_turn_id,p_lease_token) then return jsonb_build_object('kind','blocked'); end if;
  select * into c from turn_private.text_content where turn_id=p_turn_id;
  select * into p from turn_private.text_policies where id=c.policy_id;
  if p.context_mode='knowledge_intent_v1' then return jsonb_build_object('kind','blocked'); end if;
  if p.context_mode='task_history_v1' then
    history:=turn_private.task_history(p_turn_id);
    if history is null then return jsonb_build_object('kind','blocked'); end if;
    payload:=jsonb_build_object('kind','task_input','text',c.input_text,'locale',c.locale,'policyId',p.id,'provider',p.provider,'endpoint',p.endpoint,'history',history);
    return payload||jsonb_build_object('contextDigest',encode(pg_catalog.sha256(convert_to(payload::text,'UTF8')),'hex'));
  end if;
  return jsonb_build_object('kind','input','text',c.input_text,'locale',c.locale,'policyId',p.id,'provider',p.provider,'endpoint',p.endpoint);
end $function$
;

CREATE OR REPLACE FUNCTION result_data_private.schema_supported_v1()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select place_actions_private.ask_schema_v1() and ((select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check') is not distinct from 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text, ''qa_session_history_v1''::text])))') and ((select pg_get_constraintdef(k.oid) from pg_constraint k where k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check') is not distinct from 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text, ''qa_followup''::text, ''qa_correction''::text])))') and turn_private.directions_schema_members_v1() and profile_data_private.schema_v1() and result_data_private.infrastructure_supported_v1() and result_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and not(a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request')),'constraints',(select jsonb_agg(case when k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check' then 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text])))' when k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check' then 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text])))' else pg_get_constraintdef(k.oid) end order by k.conname) from pg_constraint k where k.conrelid=c.oid and not(k.conrelid='turn_private.grounded_turns'::regclass and k.conname='grounded_selected_place_request_shape'))) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)='0ec0fcfc206909a38756272a65a877c6ab857c00fd114178d135837da951c73a'
$function$
;

CREATE OR REPLACE FUNCTION result_data_private.source_v1(u uuid, root_n uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a turn_private.result_artifacts%rowtype;m turn_private.assistant_messages%rowtype;t turn_private.service_tasks%rowtype;
 refs_n jsonb:=result_data_private.empty_refs_v1();g jsonb:=result_data_private.empty_graph_v1();rows_n jsonb:='[]';reverse_n jsonb:='[]';fingerprint_n jsonb;assistant_delivery_n jsonb;directions_n jsonb;
 erase_n jsonb:=result_data_private.zero_counts_v1('erase');retain_n jsonb:=result_data_private.zero_counts_v1('retain');authorities_n jsonb:='[]';witness_n jsonb;
 spec record;v jsonb;doc_n jsonb;key_n jsonb;r record;count_key text;effect_n text;conflicts_n text[]:=array[]::text[];
 turns_n uuid[];jobs_n uuid[];impact_n uuid[];id_n uuid;tuple_n jsonb;qualified_n boolean;n integer;total_n integer:=0;raw_bytes_n bigint:=0;
begin
 select * into a from turn_private.result_artifacts where id=root_n and owner_id=u;
 if not found then raise exception 'RESULT_SOURCE_UNAVAILABLE';end if;
 select * into m from turn_private.assistant_messages where id=a.input_message_id and owner_id=u;
 select * into t from turn_private.service_tasks where id=a.task_id and owner_id=u;
 if m.id is null or t.id is null or m.goal_id<>a.goal_id or m.task_id<>a.task_id or not exists(select 1 from turn_private.assistant_goals original where original.id=a.goal_id and original.owner_id=u and original.conversation_id=m.conversation_id) then raise exception 'RESULT_SOURCE_UNAVAILABLE';end if;
 authorities_n:=jsonb_build_array(jsonb_build_object('policyId',m.policy_id,'consentId',m.consent_id),jsonb_build_object('policyId',t.policy_id,'consentId',t.consent_id));
 authorities_n:=conversation_data_private.authorities_union_v1(authorities_n);
 perform conversation_data_private.authorities_current_v1(u,authorities_n);
 if not result_data_private.schema_supported_v1() then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 refs_n:=refs_n||jsonb_build_object('conversationIds',jsonb_build_array(m.conversation_id),'goalIds',jsonb_build_array(a.goal_id),'messageIds',jsonb_build_array(m.id),
  'taskIds',jsonb_build_array(t.id),'threadIds',case when t.thread_id is null then '[]'::jsonb else jsonb_build_array(t.thread_id) end,
  'tripIds',case when a.trip_id is null then '[]'::jsonb else jsonb_build_array(a.trip_id) end,
  'sourceArtifactIds',case when a.source_result_id is null then '[]'::jsonb else jsonb_build_array(a.source_result_id) end,
  'proposalIds',case when a.proposal_id is null then '[]'::jsonb else jsonb_build_array(a.proposal_id) end);
 select conversation_data_private.union_ids_v1(array_agg(task_turn_id)||array[t.goal_turn_id,t.last_turn_id,a.source_turn_id]) into turns_n from turn_private.result_revisions where artifact_id=root_n;
 refs_n:=jsonb_set(refs_n,'{turnIds}',to_jsonb(turns_n));
 select coalesce(jsonb_agg(id order by id),'[]') into doc_n from public.memory_profiles where owner_id=u and id in(
  select coalesce(b->>'memoryId',b->>'id')::uuid from turn_private.result_revisions x cross join lateral jsonb_array_elements(x.memory_basis) b
  where x.artifact_id=root_n and notification_private.uuid(coalesce(b->'memoryId',b->'id')));
 refs_n:=jsonb_set(refs_n,'{memoryIds}',doc_n);
 if exists(select 1 from turn_private.result_revisions x cross join lateral jsonb_array_elements(x.memory_basis) basis
  where x.artifact_id=root_n and (notification_private.uuid(coalesce(basis->'memoryId',basis->'id')) is not true or not exists(select 1 from public.memory_profiles mp where mp.id::text=coalesce(basis->>'memoryId',basis->>'id') and mp.owner_id=u))) then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 select g||jsonb_build_object('artifactIds',jsonb_build_array(root_n),'revisions',coalesce(jsonb_agg(revision order by revision),'[]'),
  'publicationKeys',coalesce(jsonb_agg(idempotency_key order by idempotency_key),'[]')) into g from turn_private.result_revisions where artifact_id=root_n;
 select jsonb_set(g,'{eventIds}',coalesce(jsonb_agg(id::text order by id),'[]')) into g from turn_private.result_events where artifact_id=root_n;
 if jsonb_array_length(g->'revisions')<>a.current_revision or g->'revisions' is distinct from(select jsonb_agg(x) from generate_series(1,a.current_revision) x)
  or (select count(distinct idempotency_key) from turn_private.result_revisions where artifact_id=root_n)<>a.current_revision
  or exists(select 1 from turn_private.result_revisions where artifact_id=root_n and owner_id<>u)
  or exists(select 1 from turn_private.result_events where artifact_id=root_n and (owner_id<>u or id<=0 or revision not between 1 and a.current_revision))
  or jsonb_array_length(g->'eventIds')<a.current_revision then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if exists(select 1 from turn_private.result_revisions historical_n where historical_n.artifact_id=root_n and (historical_n.input_sequence<>m.sequence
  or not exists(select 1 from turn_private.service_task_turns st where st.turn_id=historical_n.task_turn_id and st.task_id=a.task_id and st.owner_id=u)
  or turn_private.valid_result_content_v2(historical_n.content) is not true or turn_private.valid_result_evidence_v2(historical_n.evidence_basis) is not true
  or not exists(select 1 from turn_private.result_events e where e.artifact_id=root_n and e.owner_id=u and e.revision=historical_n.revision and e.event_type=case historical_n.revision when 1 then 'ready' else 'revised' end))) then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if exists(select 1 from turn_private.result_revisions where artifact_id=root_n and (content->>'schemaVersion' not in('comparison/1','decision/1','journey-draft/1','practical/1','change-proposal-reference/1','travel-directions/1') or content->>'schemaVersion' is null)) then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if exists(select 1 from turn_private.result_revisions directions_revision where directions_revision.artifact_id=root_n and directions_revision.content->>'schemaVersion'='travel-directions/1' and not exists(select 1 from turn_private.directions_result_sources_v1 ds join turn_private.assistant_directions_intakes_v1 di on di.message_id=ds.message_id and di.owner_id=ds.owner_id where ds.artifact_id=root_n and ds.owner_id=u and ds.message_id=m.id and ds.task_turn_id=directions_revision.task_turn_id and di.task_id=a.task_id and di.goal_id=a.goal_id)) then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
 if a.proposal_id is not null or exists(select 1 from turn_private.result_revisions where artifact_id=root_n and content->>'schemaVersion'='change-proposal-reference/1') then conflicts_n:=conflicts_n||array['PROPOSAL_REFERENCE'];end if;
 if a.source_result_id is not null or exists(select 1 from turn_private.result_revisions where artifact_id=root_n and content->>'schemaVersion'='decision/1') then conflicts_n:=conflicts_n||array['DECISION_REFERENCE'];end if;
 select coalesce(array_agg(turn_id order by turn_id),array[]::uuid[]) into jobs_n from turn_private.planning_comparisons where artifact_id=root_n;
 if cardinality(jobs_n)>1 then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 for id_n in select id from turn_private.planning_v2_execution_runs where turn_id=any(jobs_n) or task_id=a.task_id loop
  if cardinality(jobs_n)=1 and result_data_private.completed_copy_v1(u,root_n,id_n) then g:=jsonb_set(g,'{executionIds}',(g->'executionIds')||to_jsonb(id_n));
  else conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
 end loop;
 for id_n in select request_id from turn_private.planning_v2_model_local_journal where turn_id=any(jobs_n) loop
  if result_data_private.journal_copy_v1(u,root_n,id_n) then g:=jsonb_set(g,'{journalIds}',(g->'journalIds')||to_jsonb(id_n));else conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
 end loop;
 if jsonb_array_length(g->'executionIds')>1 or jsonb_array_length(g->'journalIds')>1 then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 impact_n:=result_data_private.impact_sets_v1(g);
 if cardinality(impact_n)>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 -- Every fixed relation is searched for scalar, typed JSON and original BYTEA
 -- dependencies; foreign rows enter only internal hashes and blocker names.
 for spec in select * from result_data_private.relations_v1() order by relation_name collate "C" loop
  n:=0;
  for v in execute format('select to_jsonb(actual) from %s actual where result_data_private.erase_member_v1(%L,to_jsonb(actual),$1) is not null or result_data_private.source_member_v1(%L,to_jsonb(actual),$2,$3) is not null or result_data_private.related_v1(%L,to_jsonb(actual),$1) or result_data_private.reverse_binding_v1(%L,to_jsonb(actual),$3,$6) or (%L like ''knowledge_review_private.source_impact_%%'' and (to_jsonb(actual)->>''set_id''=any($4::text[]) or %L=''knowledge_review_private.source_impact_sets'' and to_jsonb(actual)->>''id''=any($4::text[]) or %L=''knowledge_review_private.source_impact_review_requests'' and (to_jsonb(actual)->>''delivery_id'' in(select id::text from knowledge_review_private.source_impact_outbox where set_id=any($4)) or to_jsonb(actual)->>''projection_id'' in(select id::text from knowledge_review_private.source_impact_projections where set_id=any($4))))) or (%L in(''export_private.core_jobs_v1'',''export_private.core_artifacts_v1'') and to_jsonb(actual)->>''owner_id''=$5::text) order by to_jsonb(actual)::text collate "C" limit 10001',
   spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name,spec.relation_name)
   using g,refs_n,jobs_n,impact_n,u,a.task_id loop
   v:=place_actions_private.ask_source_row_v1(spec.relation_name,v);
   n:=n+1;total_n:=total_n+1;raw_bytes_n:=raw_bytes_n+octet_length(v::text);
   if n>10000 or total_n>4100 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];exit;end if;
   key_n:=result_data_private.row_key_v1(v,spec.pk);
   if cardinality(spec.pk)=0 then conflicts_n:=conflicts_n||array['SOURCE_UNSUPPORTED'];end if;
   count_key:=result_data_private.erase_member_v1(spec.relation_name,v,g);effect_n:='erase';
   if count_key is null then count_key:=result_data_private.source_member_v1(spec.relation_name,v,refs_n,jobs_n);effect_n:='retain';end if;
   if count_key is not null then
    qualified_n:=v->>'owner_id'=u::text;
    if v->>'owner_id' is null then
     if spec.relation_name='public.model_budget_attempts' then qualified_n:=exists(select 1 from public.model_budget_scopes where id=(v->>'scope_id')::uuid and owner_id=u);
     elsif spec.relation_name='public.model_budget_provider_limits' then qualified_n:=exists(select 1 from public.model_budget_scopes where id=(v->>'scope_id')::uuid and owner_id=u);
     elsif spec.relation_name='turn_private.planning_v2_registered_tariffs' then qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs admitted join turn_private.planning_v2_execution_profiles profile on profile.id=admitted.profile_id where admitted.owner_id=u and g->'executionIds' ? admitted.id::text and profile.tariff_id::text=v->>'id');
     elsif spec.relation_name='turn_private.planning_v2_collector_principals' then qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs admitted where admitted.owner_id=u and g->'executionIds' ? admitted.id::text and admitted.collector_principal_id::text=v->>'id');
     elsif spec.relation_name='turn_private.text_dispatches' then qualified_n:=exists(select 1 from turn_private.text_content where turn_id=(v->>'turn_id')::uuid and owner_id=u);
     else qualified_n:=exists(select 1 from turn_private.planning_v2_execution_runs where id=(v->>'execution_id')::uuid and owner_id=u and g->'executionIds' ? id::text);end if;
    end if;
    if qualified_n is not true then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
    rows_n:=rows_n||jsonb_build_array(jsonb_build_object('table',spec.relation_name,'pk',key_n,'digest',result_data_private.digest_v1(v::text),'effect',effect_n,'countKey',count_key));
    if effect_n='erase' then erase_n:=jsonb_set(erase_n,array[count_key],to_jsonb((erase_n->>count_key)::integer+1));
    else retain_n:=jsonb_set(retain_n,array[count_key],to_jsonb((retain_n->>count_key)::integer+1));end if;
    if v->>'policy_id' is not null and v->>'consent_id' is not null then authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',v->'policy_id','consentId',v->'consent_id'));end if;
    if v->>'planning_policy_id' is not null and v->>'planning_consent_id' is not null then authorities_n:=authorities_n||jsonb_build_array(jsonb_build_object('policyId',v->'planning_policy_id','consentId',v->'planning_consent_id'));end if;
    if spec.relation_name='public.turns' and v->>'status' not in('completed','unavailable','failed','cancelled')
     or spec.relation_name='turn_private.work' and v->>'state' not in('completed','failed','cancelled')
     or spec.relation_name='turn_private.grounded_ai_assist_jobs' and v->>'status' in('queued','running')
     or spec.relation_name='turn_private.service_task_capacity' and v->>'state'='reserved'
     or spec.relation_name='public.model_budget_attempts' and v->>'status' not in('settled','released')
     or spec.relation_name='turn_private.planning_comparisons' and v->>'state'<>'completed'
     or spec.relation_name='turn_private.planning_v2_place_checkpoints' and v->>'state'<>'completed'
     or spec.relation_name='turn_private.planning_v2_model_attempt_bindings' and v->>'unknown_at' is not null
     or spec.relation_name='turn_private.planning_action_receipts' and v->>'state'<>'completed' then conflicts_n:=conflicts_n||array['ACTIVE_WORK'];end if;
    if effect_n='retain' and spec.relation_name<>'turn_private.planning_comparisons' and result_data_private.related_v1(spec.relation_name,v,g) then
     conflicts_n:=conflicts_n||case when spec.relation_name='turn_private.assistant_message_source_receipts' then 'CONVERSATION_SOURCE_REFERENCE' else 'SOURCE_UNSUPPORTED' end;
    end if;
   else
    reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',spec.relation_name,'pk',key_n,'digest',result_data_private.digest_v1(v::text)));
    conflicts_n:=conflicts_n||case
     when spec.relation_name='turn_private.result_artifacts' or spec.relation_name='turn_private.result_revisions' then case when v->'content'->>'schemaVersion'='decision/1' or v->>'source_result_id'=root_n::text then 'DECISION_REFERENCE' else 'CROSS_RESULT_REFERENCE' end
     when spec.relation_name='turn_private.assistant_message_source_receipts' then 'CONVERSATION_SOURCE_REFERENCE'
     when result_data_private.reverse_binding_v1(spec.relation_name,v,jobs_n,a.task_id) then 'SHARED_OR_FOREIGN_SCOPE'
     when spec.relation_name like 'readiness_private.%' then 'READINESS_REFERENCE' when spec.relation_name like 'guide_private.%' then 'GUIDE_REFERENCE'
     when spec.relation_name like 'scoped_edit_private.%' then 'SCOPED_EDIT_REFERENCE' when spec.relation_name like 'notification_private.%' or spec.relation_name like 'notification_exit_private.%' then 'NOTIFICATION_REFERENCE'
     when spec.relation_name like 'service_brief_private.%' then 'BRIEF_REFERENCE' when spec.relation_name like 'knowledge_review_private.source_impact_%' then 'KNOWLEDGE_MIXED_COPY'
     when spec.relation_name='public.trip_proposals' then 'PROPOSAL_REFERENCE'
     when spec.relation_name in('export_private.core_jobs_v1','export_private.core_artifacts_v1') then null
     when spec.relation_name like 'privacy_private.%' or spec.relation_name like 'conversation_data_private.%' then 'OTHER_DELETE_PENDING'
     else 'SOURCE_UNSUPPORTED' end;
   end if;
  end loop;
  if 'SCOPE_TOO_LARGE'=any(conflicts_n) then exit;end if;
 end loop;
 -- References and source identities are owner-qualified exactly, including every
 -- historical turn; absence/foreign mismatch is never reported as an eligible graph.
 if (retain_n->>'conversations')::integer<>1 or (retain_n->>'goals')::integer<>1 or (retain_n->>'messages')::integer<>1 or (retain_n->>'tasks')::integer<>1
  or (retain_n->>'turns')::integer<>cardinality(turns_n)
  or (retain_n->>'threads')::integer<>jsonb_array_length(refs_n->'threadIds')
  or (retain_n->>'trips')::integer<>jsonb_array_length(refs_n->'tripIds')
  or (retain_n->>'sourceArtifacts')::integer<>jsonb_array_length(refs_n->'sourceArtifactIds')
  or (retain_n->>'proposals')::integer<>jsonb_array_length(refs_n->'proposalIds') then conflicts_n:=conflicts_n||array['SHARED_OR_FOREIGN_SCOPE'];end if;
 if exists(select 1 from export_private.core_artifacts_v1 where owner_id=u) or exists(select 1 from export_private.core_jobs_v1 where owner_id=u and (state in('queued','running') or lease_expires_at>clock_timestamp())) then conflicts_n:=conflicts_n||array['CORE_EXPORT_COPY'];end if;
 if exists(select 1 from privacy_private.trip_deletions where owner_id=u and state='queued' and refs_n->'tripIds' ? trip_id::text)
  or exists(select 1 from privacy_private.linked_delete_fences_v1 where entity_id=root_n or refs_n->'turnIds' ? entity_id::text)
  or exists(select 1 from privacy_private.memory_delete_jobs_v1 j join privacy_private.memory_delete_plans_v1 p on p.id=j.plan_id where j.owner_id=u and j.state='queued' and (p.selection->'artifactIds' ? root_n::text or privacy_private.memory_delete_ids_v1(p.selection)&&privacy_private.linked_delete_array_v1(refs_n->'memoryIds')))
  or exists(select 1 from conversation_data_private.operations_v1 o where owner_id=u and state='previewed' and not preview_erased and expires_at>floor(extract(epoch from clock_timestamp())*1000)::bigint and (o.graph->'artifactIds' ? root_n::text or o.graph->'taskIds' ? a.task_id::text or o.graph->'turnIds' ?| array(select jsonb_array_elements_text(refs_n->'turnIds'))))
  or exists(select 1 from conversation_data_private.operations_v1 o where state='erased' and (o.decision->'graph'->'artifactIds' ? root_n::text or o.decision->'graph'->'taskIds' ? a.task_id::text)) then conflicts_n:=conflicts_n||array['OTHER_DELETE_PENDING'];end if;
 for r in select * from result_data_private.deletion_witnesses_v1(u,refs_n,g) order by relation_name collate "C",document_n::text collate "C" limit 4101 loop
  total_n:=total_n+1;raw_bytes_n:=raw_bytes_n+octet_length(r.document_n::text);
  select pk into spec from result_data_private.relations_v1() where relation_name=r.relation_name;
  key_n:=case when r.relation_name='conversation_data_private.operations_v1' then jsonb_build_object('request_id',r.document_n->'request_id') else result_data_private.row_key_v1(r.document_n,spec.pk) end;
  reverse_n:=reverse_n||jsonb_build_array(jsonb_build_object('table',r.relation_name,'pk',key_n,'digest',result_data_private.digest_v1(r.document_n::text)));
  conflicts_n:=conflicts_n||array['OTHER_DELETE_PENDING'];
 end loop;
 authorities_n:=conversation_data_private.authorities_union_v1(authorities_n);
 if jsonb_array_length(authorities_n)>100 then raise exception 'RESULT_CAPACITY';end if;
 witness_n:=conversation_data_private.authorities_current_v1(u,authorities_n);
 assistant_delivery_n:=turn_private.assistant_delivery_source_v1(u,g);
 directions_n:=turn_private.directions_source_witness_v1(u,'result',g);
 fingerprint_n:=jsonb_build_object('directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'graph',g,'rows',rows_n,'reverse',reverse_n,'retainedReferences',refs_n,'authorities',authorities_n,'witness',witness_n,'conflicts',result_data_private.conflicts_v1(conflicts_n));
 if (directions_n->>'rowCount')::integer+jsonb_array_length(assistant_delivery_n->'rows')+total_n+coalesce(jsonb_array_length(witness_n),0)>4100 or raw_bytes_n+(directions_n->>'bytes')::bigint>1000000 or (select sum(jsonb_array_length(value)) from jsonb_each(g))>4100 or octet_length(fingerprint_n::text)>1000000 or jsonb_array_length(g->'eventIds')>3000 then conflicts_n:=conflicts_n||array['SCOPE_TOO_LARGE'];end if;
 if 'SCOPE_TOO_LARGE'=any(conflicts_n) then
  g:=jsonb_set(result_data_private.empty_graph_v1(),'{artifactIds}',jsonb_build_array(root_n));refs_n:=result_data_private.empty_refs_v1();
  erase_n:=result_data_private.zero_counts_v1('erase');retain_n:=result_data_private.zero_counts_v1('retain');rows_n:='[]';
 end if;
 return jsonb_build_object('graph',g,'eraseCounts',erase_n,'retainCounts',retain_n,'retainedReferences',refs_n,'conflicts',result_data_private.conflicts_v1(conflicts_n),
  'sourceAuthorities',authorities_n,'rows',rows_n,'reverse',reverse_n,'directionsSource',directions_n,'assistantDelivery',assistant_delivery_n,'sourceDigest',result_data_private.digest_v1(fingerprint_n::text));
end$function$
;

CREATE OR REPLACE FUNCTION turn_data_private.export_row_v1(rel text, v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare c record;out_n jsonb:=place_actions_private.ask_source_row_v1(rel,v);begin
 for c in select attname from pg_attribute where attrelid=rel::regclass and attnum>0 and not attisdropped and atttypid in('int8'::regtype,'xid8'::regtype) loop
  if v->c.attname<>'null'::jsonb then out_n:=jsonb_set(out_n,array[c.attname::text],to_jsonb(v->>c.attname));end if;
 end loop;return out_n;
end$function$
;

CREATE OR REPLACE FUNCTION turn_data_private.export_source_v1(u uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare roots uuid[];msgs uuid[];arts uuid[];tasks uuid[];ex uuid[];g jsonb;refs jsonb;s record;v jsonb;r jsonb;group_rows jsonb[];groups_n jsonb[]:=array[]::jsonb[];ops jsonb[]:=array[]::jsonb[];fences jsonb[]:=array[]::jsonb[];source_keys jsonb[]:=array[]::jsonb[];op_n turn_data_private.operations_v1;key_count integer;sort_n text;
 auths jsonb:='[]';identity_n uuid;row_count_n integer:=0;byte_count_n integer:=0;item jsonb;witness jsonb;st text;
begin
 if turn_data_private.runtime_supported_v1() is not true or turn_data_private.schema_supported_v1() is not true or u is null or not exists(select 1 from auth.users where id=u) then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
 select turn_data_private.union_ids_v1(array_agg(id)) into roots from(select id from public.turns where owner_id=u union select turn_id from turn_private.text_content where owner_id=u) a;
 if cardinality(roots)>10000 then raise exception 'TURN_CAPACITY';end if;
 for identity_n in select unnest(roots) order by 1 loop if not pg_try_advisory_xact_lock(hashtextextended('turn-data-entity:turnIds:'||identity_n::text,0)) then raise lock_not_available using message='TURN_CONFLICT';end if;end loop;
 select turn_data_private.union_ids_v1(array_agg(id)) into arts from turn_private.result_artifacts a where a.source_turn_id=any(roots) or exists(select 1 from turn_private.result_revisions r where r.artifact_id=a.id and r.task_turn_id=any(roots));
 select turn_data_private.union_ids_v1(array_agg(id)) into msgs from turn_private.assistant_messages m where m.turn_id=any(roots) or exists(select 1 from turn_private.planning_comparisons p where p.turn_id=any(roots) and p.message_id=m.id) or exists(select 1 from turn_private.result_artifacts a where a.id=any(arts) and a.input_message_id=m.id)
  or exists(select 1 from turn_private.assistant_directions_intakes_v1 retained_i
 join turn_private.assistant_messages owned_message on owned_message.id=retained_i.message_id and owned_message.owner_id=u
 join turn_private.assistant_conversations owned_conversation on owned_conversation.id=retained_i.conversation_id and owned_conversation.owner_id=u
 join turn_private.assistant_goals owned_goal on owned_goal.id=retained_i.goal_id and owned_goal.owner_id=u and owned_goal.conversation_id=owned_conversation.id
 join turn_private.service_tasks owned_task on owned_task.id=retained_i.task_id and owned_task.owner_id=u
 join turn_private.service_task_turns owned_task_turn on owned_task_turn.turn_id=retained_i.task_turn_id and owned_task_turn.task_id=owned_task.id and owned_task_turn.owner_id=u
 join public.turns owned_turn on owned_turn.id=retained_i.task_turn_id and owned_turn.owner_id=u
 join turn_private.text_content owned_text on owned_text.turn_id=owned_turn.id and owned_text.owner_id=u
 where retained_i.owner_id=u and retained_i.task_turn_id=any(roots)
 and owned_message.relationship='follow_up' and owned_message.turn_id is null
 and owned_message.task_id=owned_task.id and owned_message.conversation_id=owned_conversation.id and owned_message.goal_id=owned_goal.id
 and owned_message.sequence=retained_i.message_sequence and owned_message.scope_version=retained_i.goal_version
 and owned_message.policy_id=retained_i.policy_id and owned_message.consent_id=retained_i.consent_id
 and owned_task.policy_id=retained_i.policy_id and owned_task.consent_id=retained_i.consent_id
 and owned_text.policy_id=retained_i.policy_id and owned_text.consent_id=retained_i.consent_id
 and owned_turn.thread_id=owned_task.thread_id and owned_text.thread_id=owned_task.thread_id and retained_i.message_id=m.id);
 select turn_data_private.union_ids_v1(array_agg(task_id)) into tasks from(select task_id from turn_private.service_task_turns where turn_id=any(roots) union select task_id from turn_private.assistant_messages where id=any(msgs) union select task_id from turn_private.result_artifacts where id=any(arts) union select task_id from turn_private.planning_comparisons where turn_id=any(roots)) a;
 select turn_data_private.union_ids_v1(array_agg(id)) into ex from turn_private.planning_v2_execution_runs where turn_id=any(roots) and owner_id=u;
 g:=jsonb_build_object('turnIds',roots,'messageIds',msgs,'artifactIds',arts);refs:=jsonb_build_object('taskIds',tasks);
 for s in select * from turn_data_private.sources_v1() order by array_position(array['public.chat_turn_events','public.chat_turn_idempotency','public.memory_consumer_receipts','public.model_budget_attempts','public.turn_feedback','turn_private.assistant_message_source_receipts','turn_private.assistant_messages','turn_private.assistant_travel_intakes','turn_private.grounded_ai_assist_jobs','turn_private.grounded_turns','turn_private.planning_action_receipts','turn_private.planning_comparisons','turn_private.planning_intake_bindings','turn_private.planning_model_dispatches','turn_private.planning_observations','turn_private.planning_v2_collector_origins','turn_private.planning_v2_collector_outputs','turn_private.planning_v2_completed_receipts','turn_private.planning_v2_completion_proofs','turn_private.planning_v2_execution_runs','turn_private.planning_v2_external_call_windows','turn_private.planning_v2_model_attempt_bindings','turn_private.planning_v2_model_local_journal','turn_private.planning_v2_place_checkpoints','turn_private.planning_v2_result_claims','turn_private.result_artifacts','turn_private.result_events','turn_private.result_revisions','turn_private.service_task_capacity','turn_private.service_task_turns','turn_private.service_tasks','turn_private.text_content','turn_private.text_dispatches','turn_private.work','public.turns']::text[],relation_name) loop
  group_rows:=array[]::jsonb[];
  for v in execute format('select to_jsonb(a) from %s a where %s order by %s limit 10001 for share nowait',s.relation_name,turn_data_private.export_predicate_v1(s.relation_name),(select string_agg(format('a.%I',k),',') from unnest(s.pk) k)) using roots,msgs,arts,tasks,ex,u loop
   if s.has_owner and v->>'owner_id' is distinct from u::text then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   if s.count_key='sourceReceipts' and (jsonb_typeof(v->'input_sources'->'evidence') is distinct from 'array' or jsonb_array_length(v->'input_sources'->'evidence')>0) then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   if s.count_key='attemptBindings' and not exists(select 1 from turn_private.planning_comparisons pc join turn_private.text_content tc on tc.turn_id=pc.turn_id and tc.owner_id=pc.owner_id where pc.turn_id=(v->>'turn_id')::uuid and pc.owner_id=u and pc.task_id=(v->>'task_id')::uuid and pc.planning_policy_id=(v->>'planning_policy_id')::uuid and tc.policy_id=(v->>'text_policy_id')::uuid) then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   if s.count_key='grounded' then
    if v->'selected_place_request' is distinct from 'null'::jsonb and v ? 'selected_place_request' then
     if not place_actions_private.ask_proof_shape_v1(v->'selected_place_request') or not place_actions_private.ask_answer_basis_shape_v1(v->'basis')
      or v->'selected_place_request'->'originalReceipt'->'turnId' is distinct from v->'turn_id' or v->'selected_place_request'->'originalReceipt'->'serviceTaskId' is distinct from v->'task_id' then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
    elsif jsonb_typeof(v->'basis'->'publications') is distinct from 'array' or jsonb_array_length(v->'basis'->'publications')>0 then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   end if;
   r:=turn_data_private.export_row_v1(s.relation_name,v);row_count_n:=row_count_n+1;byte_count_n:=byte_count_n+octet_length(r::text);
   if row_count_n>10000 or byte_count_n>1000000 then raise exception 'TURN_CAPACITY';end if;
   group_rows:=array_append(group_rows,r);
   if v->>'policy_id' is not null and v->>'consent_id' is not null then auths:=auths||jsonb_build_array(jsonb_build_object('policyId',v->'policy_id','consentId',v->'consent_id'));end if;
   if v->>'planning_policy_id' is not null and v->>'planning_consent_id' is not null then auths:=auths||jsonb_build_array(jsonb_build_object('policyId',v->'planning_policy_id','consentId',v->'planning_consent_id'));end if;
  end loop;
  groups_n:=array_append(groups_n,jsonb_build_object('relation',s.relation_name,'rows',to_jsonb(group_rows)));
 end loop;
 -- New conversations sections share the original qualified snapshot/sourceState
 -- digest and managed-copy qualification; no new module/provenance authority.
 for s in select * from(values
  ('turn_private.assistant_directions_intakes_v1'::text,'message_id'::text),
  ('turn_private.directions_result_sources_v1','artifact_id'),
  ('turn_private.directions_operations_v1','operation_id')) exact_sources(relation_name,key_name) loop
  group_rows:=array[]::jsonb[];
  for v in execute format('select to_jsonb(a) from %s a where owner_id=$1 order by %I limit 10001 for share nowait',s.relation_name,s.key_name) using u loop
   if v->>'owner_id' is distinct from u::text then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   if s.relation_name='turn_private.assistant_directions_intakes_v1' and not exists(select 1 from turn_private.assistant_directions_intakes_v1 retained_i
 join turn_private.assistant_messages owned_message on owned_message.id=retained_i.message_id and owned_message.owner_id=u
 join turn_private.assistant_conversations owned_conversation on owned_conversation.id=retained_i.conversation_id and owned_conversation.owner_id=u
 join turn_private.assistant_goals owned_goal on owned_goal.id=retained_i.goal_id and owned_goal.owner_id=u and owned_goal.conversation_id=owned_conversation.id
 join turn_private.service_tasks owned_task on owned_task.id=retained_i.task_id and owned_task.owner_id=u
 join turn_private.service_task_turns owned_task_turn on owned_task_turn.turn_id=retained_i.task_turn_id and owned_task_turn.task_id=owned_task.id and owned_task_turn.owner_id=u
 join public.turns owned_turn on owned_turn.id=retained_i.task_turn_id and owned_turn.owner_id=u
 join turn_private.text_content owned_text on owned_text.turn_id=owned_turn.id and owned_text.owner_id=u
 where retained_i.owner_id=u and retained_i.task_turn_id=any(roots)
 and owned_message.relationship='follow_up' and owned_message.turn_id is null
 and owned_message.task_id=owned_task.id and owned_message.conversation_id=owned_conversation.id and owned_message.goal_id=owned_goal.id
 and owned_message.sequence=retained_i.message_sequence and owned_message.scope_version=retained_i.goal_version
 and owned_message.policy_id=retained_i.policy_id and owned_message.consent_id=retained_i.consent_id
 and owned_task.policy_id=retained_i.policy_id and owned_task.consent_id=retained_i.consent_id
 and owned_text.policy_id=retained_i.policy_id and owned_text.consent_id=retained_i.consent_id
 and owned_turn.thread_id=owned_task.thread_id and owned_text.thread_id=owned_task.thread_id and retained_i.message_id=(v->>'message_id')::uuid) then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   r:=turn_data_private.export_row_v1(s.relation_name,v);
   row_count_n:=row_count_n+1;byte_count_n:=byte_count_n+octet_length(r::text);
   if row_count_n>10000 or byte_count_n>1000000 then raise exception 'TURN_CAPACITY';end if;
   group_rows:=array_append(group_rows,r);
   if v->>'policy_id' is not null and v->>'consent_id' is not null then auths:=auths||jsonb_build_array(jsonb_build_object('policyId',v->'policy_id','consentId',v->'consent_id'));end if;
   if v->>'planning_policy_id' is not null and v->>'planning_consent_id' is not null then auths:=auths||jsonb_build_array(jsonb_build_object('policyId',v->'planning_policy_id','consentId',v->'planning_consent_id'));end if;
  end loop;
  groups_n:=array_append(groups_n,jsonb_build_object('relation',s.relation_name,'rows',to_jsonb(group_rows)));
 end loop;
 for r in select turn_data_private.operation_row_v1(a) from turn_data_private.operations_v1 a where owner_id=u order by request_id limit 10001 for share nowait loop
  row_count_n:=row_count_n+1;byte_count_n:=byte_count_n+octet_length(r::text);if row_count_n>10000 or byte_count_n>1000000 then raise exception 'TURN_CAPACITY';end if;ops:=array_append(ops,r);auths:=auths||(r->'sourceAuthorities');
 end loop;
 for r in select jsonb_build_object('kind',kind_n,'objectId',id_n,'requestId',request_id,'createdAt',created_n) from (
  select distinct on(kind_n collate "C",id_n) kind_n,id_n,request_id,created_n from(
   select case e.key when 'turnIds' then 'turn' when 'messageIds' then 'message' else 'artifact' end kind_n,(x.value#>>'{}')::uuid id_n,a.request_id,(a.decision->>'decidedAt')::bigint created_n
    from turn_data_private.operations_v1 a cross join lateral jsonb_each(a.decision->'graph') e cross join lateral jsonb_array_elements(e.value) x where a.owner_id=u and a.state='erased' and a.scope='turn-sensitive-data/1'
   union all select 'operation',obj,request_id,(decision->>'decidedAt')::bigint from turn_data_private.operations_v1 a cross join lateral unnest(a.object_ids) obj where a.owner_id=u and a.state='erased' and a.scope='turn-delete-progress/1'
  ) all_n order by kind_n collate "C",id_n,created_n,request_id
 ) a order by kind_n collate "C",id_n loop
  row_count_n:=row_count_n+1;byte_count_n:=byte_count_n+octet_length(r::text);if row_count_n>10000 or byte_count_n>1000000 then raise exception 'TURN_CAPACITY';end if;fences:=array_append(fences,r);
 end loop;
 -- Exact private terminal source-PK proof, in request/relation/native-PK order.
 for op_n in select * from turn_data_private.operations_v1 where owner_id=u and scope='turn-sensitive-data/1' and state='erased' order by request_id for share nowait loop
  key_count:=0;
  if jsonb_typeof(op_n.source_identity_keys) is distinct from 'array' then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
  for s in select * from turn_data_private.sources_v1() where effect='erase' order by relation_name collate "C" loop
   select string_agg(format('((key->''pk''->>%L)::%s)',k,format_type(a.atttypid,a.atttypmod)),',' order by ord) into sort_n from unnest(s.pk) with ordinality p(k,ord) join pg_attribute a on a.attrelid=s.relation_name::regclass and a.attname=k and a.attnum>0 and not a.attisdropped;
   if (select count(*) from jsonb_array_elements(op_n.source_identity_keys) key where key->>'relation'=s.relation_name) is distinct from (op_n.decision->'erasedCounts'->>s.count_key)::integer then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
   for v in execute format('select key->''pk'' from jsonb_array_elements($1) key where key->>''relation''=$2 order by %s',sort_n) using op_n.source_identity_keys,s.relation_name loop
    if notification_private.exact(v,s.pk) is not true then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
    key_count:=key_count+1;r:=jsonb_build_object('requestId',op_n.request_id,'relation',s.relation_name,'pk',turn_data_private.export_row_v1(s.relation_name,v));
    row_count_n:=row_count_n+1;byte_count_n:=byte_count_n+octet_length(r::text);
    if row_count_n>10000 or byte_count_n>1000000 then raise exception 'TURN_CAPACITY';end if;
    source_keys:=array_append(source_keys,r);
   end loop;
  end loop;
  if key_count<>jsonb_array_length(op_n.source_identity_keys) then raise exception 'TURN_SOURCE_UNAVAILABLE';end if;
 end loop;
 auths:=turn_data_private.authorities_union_v1(auths);witness:=turn_data_private.authorities_current_v1(u,auths);
 item:=jsonb_build_object('ownerId',u,'sources',to_jsonb(groups_n),'operations',to_jsonb(ops),'fences',to_jsonb(fences),'sourceIdentityKeys',to_jsonb(source_keys),'sourceRows',jsonb_build_object('data',row_count_n-cardinality(ops)-cardinality(fences)-cardinality(source_keys),'operations',cardinality(ops),'fences',cardinality(fences),'sourceIdentityKeys',cardinality(source_keys)),'sourceAuthorities',auths);
 -- One final canonical pass; row/byte accumulation above never serializes a growing snapshot.
 st:=notification_private.canonical(jsonb_build_object('snapshot',jsonb_build_array(item)));
 if octet_length(st)>1000000 then raise exception 'TURN_CAPACITY';end if;
 return jsonb_build_object('snapshot',item,'sourceDigest',turn_data_private.digest_v1(st),'sourceStateDigest',turn_data_private.digest_v1(jsonb_build_array(item,witness)::text));
end$function$
;

CREATE OR REPLACE FUNCTION turn_data_private.guard_source_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare rel text:=tg_table_schema||'.'||tg_table_name;nv jsonb:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;ov jsonb:=case when tg_op='INSERT' then to_jsonb(new) else to_jsonb(old) end;r record;owners uuid[];key_n jsonb;
begin
 if rel='turn_private.grounded_turns' and tg_op='UPDATE' and ov->'selected_place_request' is distinct from nv->'selected_place_request' then raise exception 'IMMUTABLE_BINDING';end if;
 owners:=turn_data_private.union_ids_v1(array[nullif(nv->>'owner_id','')::uuid,nullif(ov->>'owner_id','')::uuid]);
 if cardinality(owners)>0 and not exists(select 1 from auth.users where id=any(owners)) and tg_op='DELETE' then return old;end if;
 for key_n in select distinct k from(select turn_data_private.source_key_v1(rel,nv) k union select turn_data_private.source_key_v1(rel,ov) where tg_op='UPDATE' and ov is distinct from nv) a where k is not null loop
  if not pg_try_advisory_xact_lock_shared(hashtextextended('turn-data-source-key:'||rel||':'||turn_data_private.digest_v1(key_n::text),0)) then raise lock_not_available using message='TURN_CONFLICT';end if;
  if turn_data_private.source_key_fenced_v1(rel,key_n) then raise exception 'TURN_CONFLICT';end if;
 end loop;
