 return conversation_data_private.schema_supported_v1() and result_data_private.infrastructure_supported_v1() and result_data_private.digest_v1((select coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and not(a.attrelid='turn_private.grounded_turns'::regclass and a.attname='selected_place_request')),'constraints',(select jsonb_agg(case when k.conrelid='turn_private.text_policies'::regclass and k.conname='text_policies_context_mode_check' then 'CHECK ((context_mode = ANY (ARRAY[''current_input_v1''::text, ''task_history_v1''::text, ''knowledge_intent_v1''::text])))' when k.conrelid='turn_private.service_task_turns'::regclass and k.conname='service_task_turns_relationship_check' then 'CHECK ((relationship = ANY (ARRAY[''new_goal''::text, ''clarification''::text, ''repair''::text])))' else pg_get_constraintdef(k.oid) end order by k.conname) from pg_constraint k where k.conrelid=c.oid and not(k.conrelid='turn_private.grounded_turns'::regclass and k.conname='grounded_selected_place_request_shape'))) order by n.nspname,c.relname),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and n.nspname not in('pg_catalog','information_schema','extensions','auth','result_data_private','storage','realtime','_realtime','vault','supabase_functions','supabase_migrations'))::text)='0ec0fcfc206909a38756272a65a877c6ab857c00fd114178d135837da951c73a';
